{
  "name": "Sentinel - Bharat Omega",
  "description": "A dark-themed, tactical dashboard for government tender analysis, featuring RFP risk scanning, pre-bid query drafting, and Make-in-India L1 calculations."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum View {
  DASHBOARD = 'dashboard',
  ANALYZER = 'analyzer',
  PREBID = 'prebid',
  CALCULATOR = 'calculator',
  VAULT = 'vault'
}

export interface CalculatorItem {
  id: string;
  name: string;
  hsCode: string;
  importCost: number;
  localCost: number;
}

import React, { useState } from 'react';
import { View } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Analyzer from './components/Analyzer';
import PreBidStudio from './components/PreBidStudio';
import Calculator from './components/Calculator';
import Vault from './components/Vault';
import VerificationModal from './components/VerificationModal';

export default function App() {
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // SVG User Profile Base64
  const userProfileSvg = `data:image/svg+xml;base64,`;

  const renderView = () => {
    switch (currentView) {
      case View.DASHBOARD:
        return <Dashboard onViewChange={setCurrentView} />;
      case View.ANALYZER:
        return <Analyzer onViewChange={setCurrentView} />;
      case View.PREBID:
        return <PreBidStudio onViewChange={setCurrentView} onOpenModal={() => setIsModalOpen(true)} />;
      case View.CALCULATOR:
        return <Calculator />;
      case View.VAULT:
        return <Vault />;
      default:
        return <Dashboard onViewChange={setCurrentView} />;
    }
  };

  return (
    <div className="flex h-screen overflow-hidden text-sm bg-slate-950 text-slate-200">
      {/* Sidebar */}
      <Sidebar currentView={currentView} onViewChange={setCurrentView} />

      {/* Main Content */}
      <main className="flex-1 flex flex-col relative bg-slate-950">
        {/* Header */}
        <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-md sticky top-0 z-10 shrink-0">
          <div className="flex items-center gap-4">
            <span className="px-2 py-1 bg-amber-500/10 text-amber-500 text-xs font-mono rounded border border-amber-500/20 animate-pulse">
              LIVE FEED ACTIVE
            </span>
            <span className="text-slate-400 text-xs hidden sm:inline">
              Last Sync: <span className="font-mono text-cyan-400">14:02:45 IST</span>
            </span>
          </div>
          <div className="flex items-center gap-4">
            <button className="p-2 text-slate-400 hover:text-white relative transition-colors">
              <span className="material-symbols-outlined">notifications</span>
              <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full"></span>
            </button>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-full bg-slate-700 overflow-hidden border border-slate-600">
                <img alt="User" className="w-full h-full object-cover" src={userProfileSvg} />
              </div>
              <div className="text-xs hidden sm:block">
                <p className="text-white font-medium">Rajesh Verma</p>
                <p className="text-slate-500">Defense Electronics Ltd</p>
              </div>
            </div>
          </div>
        </header>

        {/* View Container */}
        <div className="flex-1 overflow-y-auto overflow-x-hidden p-6 relative">
          {renderView()}
        </div>
      </main>

      {/* Modal */}
      <VerificationModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
    </div>
  );
}

import React from 'react';
import { View } from '../types';

