};

export default Sidebar;

import React, { useState } from 'react';
import { View } from '../types';

interface AnalyzerProps {
  onViewChange: (view: View) => void;
}

const Analyzer: React.FC<AnalyzerProps> = ({ onViewChange }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [selectedClauseId, setSelectedClauseId] = useState<string | null>(null);

  const triggerScan = () => {
    setIsScanning(true);
    setTimeout(() => {
      setIsScanning(false);
      // Automatically select the bad clause after scan simulates detection
      setSelectedClauseId('clause-4.2');
    }, 2000);
  };

  const handleClauseClick = (id: string) => {
    setSelectedClauseId(id);
  };

  return (
    <div className="space-y-6 h-full flex flex-col fade-in">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-white">RFP Analyzer</h2>
        <button 
          className="bg-cyan-600 hover:bg-cyan-500 text-white px-4 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors shadow-lg shadow-cyan-900/50" 
          onClick={triggerScan}
          disabled={isScanning}
        >
          <span className="material-symbols-outlined text-sm">{isScanning ? 'hourglass_top' : 'upload_file'}</span>
          {isScanning ? 'Scanning...' : 'Upload Tender PDF'}
        </button>
      </div>

      <div className="grid grid-cols-12 gap-6 flex-1 min-h-0">
        {/* Left: Document Preview */}
        <div className={`col-span-12 lg:col-span-7 glass-panel rounded-xl overflow-hidden flex flex-col relative scanner-container ${isScanning ? 'scanning' : ''}`}>
          <div className="scanner-line"></div>
          <div className="bg-slate-900 p-2 border-b border-slate-800 flex justify-between items-center">
            <span className="text-xs font-mono text-slate-400">Nagpur_Smart_City_RFP_v2.pdf (Page 42/108)</span>
            <div className="flex gap-2">
              <span className="w-3 h-3 rounded-full bg-red-500 cursor-pointer" title="High Risk"></span>
              <span className="w-3 h-3 rounded-full bg-amber-500 cursor-pointer" title="Medium Risk"></span>
              <span className="w-3 h-3 rounded-full bg-green-500 cursor-pointer" title="Safe"></span>
            </div>
          </div>
          <div className="flex-1 bg-white p-8 text-slate-900 font-serif text-sm overflow-y-auto relative selection:bg-cyan-200">
            {/* Simulated PDF Content */}
            <div className="max-w-3xl mx-auto space-y-6">
              <p className="text-center font-bold text-lg border-b pb-4 border-slate-200">SECTION IV: TECHNICAL SPECIFICATIONS</p>

              <div 
                className={`p-3 rounded cursor-pointer transition-colors border ${selectedClauseId === 'clause-4.1' ? 'ring-2 ring-cyan-400 bg-cyan-50 border-cyan-200' : 'hover:bg-slate-100 border-transparent'}`}
