                onClick={() => handleClauseClick('clause-4.4')}
              >
                <span className="font-bold">4.4 Hardware OEM</span><br/>
                The OEM for cameras must have been operating in India for at least 10 years and have a turnover of $500M.
              </div>
            </div>
          </div>
