        {/* Right: AI Findings */}
        <div className="col-span-12 lg:col-span-5 flex flex-col gap-4">
          <div className="glass-panel p-4 rounded-xl flex-1 flex flex-col">
            <div className="flex items-center gap-2 mb-4 border-b border-slate-800 pb-2">
