                    </div>
                  </div>
                  <div className="flex items-center gap-2 p-2 bg-slate-800 rounded border border-slate-700">
                    <span className="material-symbols-outlined text-amber-500 text-sm">gavel</span>
                    <div className="text-xs">
                      <p className="text-white">MeitY Empanelment</p>
                      <p className="text-slate-500">Cloud Service Provider Requirements</p>
                    </div>
                  </div>
                </div>

                <div className="mt-auto pt-4 border-t border-slate-800">
                  <button 
                    className="w-full bg-cyan-600 hover:bg-cyan-500 text-white py-3 rounded-lg font-medium flex items-center justify-center gap-2 transition-all shadow-lg shadow-cyan-900/50"
                    onClick={() => onViewChange(View.PREBID)}
