import React, { useState, useEffect } from 'react';
import { CalculatorItem } from '../types';

const Calculator: React.FC = () => {
  const [items, setItems] = useState<CalculatorItem[]>([
    { id: '1', name: 'Ruggedized PCB Mainboard', hsCode: '8542.31', importCost: 15000, localCost: 5000 },
    { id: '2', name: 'Chassis & Housing (Metal)', hsCode: '7326.90', importCost: 0, localCost: 8000 },
    { id: '3', name: 'LCD Panel (10 inch)', hsCode: '8524.30', importCost: 12000, localCost: 0 },
    { id: '4', name: 'Assembly & Testing Services', hsCode: '9988', importCost: 0, localCost: 18000 },
  ]);

  const [localContentPercent, setLocalContentPercent] = useState(0);
  const [isOptimizing, setIsOptimizing] = useState(false);

  useEffect(() => {
    let totalImport = 0;
    let totalLocal = 0;

    items.forEach(item => {
      totalImport += item.importCost || 0;
      totalLocal += item.localCost || 0;
    });

    const total = totalImport + totalLocal;
    const percent = total > 0 ? (totalLocal / total) * 100 : 0;
    setLocalContentPercent(percent);
  }, [items]);

  const updateItem = (id: string, field: 'importCost' | 'localCost', value: string) => {
    const numValue = parseFloat(value) || 0;
    setItems(prev => prev.map(item => 
      item.id === id ? { ...item, [field]: numValue } : item
    ));
  };

  const deleteItem = (id: string) => {
    setItems(prev => prev.filter(item => item.id !== id));
  };

  const addItem = () => {
    const newId = (Math.max(...items.map(i => parseInt(i.id))) + 1).toString();
    setItems([...items, { id: newId, name: 'New Component', hsCode: '0000', importCost: 0, localCost: 0 }]);
  };

  const handleAiOptimize = () => {
      setIsOptimizing(true);
      setTimeout(() => {
          // AI Logic: Find an imported item and switch it to local vendor (e.g., Havells)
          // As per PDF: Switch 'Power Cord Supply' or similar small items
          setItems(prev => {
             const newItems = [...prev];
             // Identify the LCD Panel or similar imported item to swap
             const targetIndex = newItems.findIndex(i => i.importCost > 0);
             if (targetIndex !== -1) {
                 const item = newItems[targetIndex];
                 // Convert 100% import to 100% local for this item to simulate "Switching Vendor"
                 // In reality, cost might change, but for demo we swap values
                 newItems[targetIndex] = {
                     ...item,
                     name: `${item.name} (Local Vendor: Havells)`,
                     localCost: item.importCost + 500, // Slight cost increase
                     importCost: 0
                 };
             }
             return newItems;
          });
          setIsOptimizing(false);
      }, 1500);
  };

  // Determine Class Status
  let statusColor = 'text-red-500';
  let statusBorder = 'border-red-500';
  let strokeColor = '#ef4444';
  let statusTitle = 'Non-Local Supplier';
  let statusDesc = 'May be disqualified if sufficient local capacity exists.';

  if (localContentPercent >= 50) {
    statusColor = 'text-green-500';
    statusBorder = 'border-green-500';
    strokeColor = '#22c55e';
    statusTitle = 'Class-I Local Supplier';
    statusDesc = 'Eligible for 20% Purchase Preference margin over L1.';
  } else if (localContentPercent >= 20) {
    statusColor = 'text-amber-500';
    statusBorder = 'border-amber-500';
    strokeColor = '#f59e0b';
    statusTitle = 'Class-II Local Supplier';
    statusDesc = 'Eligible for bid participation, but NO Purchase Preference.';
  }

  // Circle calculation
  const radius = 70;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (localContentPercent / 100) * circumference;

  return (
    <div className="space-y-6 h-full flex flex-col fade-in">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-white">Make-in-India (Class-I) Calculator</h2>
        <button 
            onClick={handleAiOptimize}
            disabled={localContentPercent >= 50 || isOptimizing}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all shadow-lg ${localContentPercent >= 50 ? 'bg-green-900/50 text-green-400 cursor-not-allowed' : 'bg-purple-600 hover:bg-purple-500 text-white shadow-purple-900/50'}`}
        >
             <span className="material-symbols-outlined text-sm">{isOptimizing ? 'settings_motion_mode' : 'auto_fix_high'}</span>
             {isOptimizing ? 'Optimizing BOM...' : localContentPercent >= 50 ? 'Optimization Complete' : 'AI Optimize for Class-I'}
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 flex-1 min-h-0 overflow-y-auto">
        {/* Controls */}
        <div className="lg:col-span-8 glass-panel rounded-xl overflow-hidden flex flex-col">
          <div className="flex-1 overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-900 text-slate-400 text-xs uppercase sticky top-0 z-10">
                <tr>
                  <th className="p-4 font-semibold">Component Name</th>
                  <th className="p-4 font-semibold">HS Code</th>
                  <th className="p-4 text-right font-semibold">Import Cost (₹)</th>
                  <th className="p-4 text-right font-semibold">Local Cost (₹)</th>
                  <th className="p-4 text-center font-semibold">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800">
                {items.map(item => (
                  <tr key={item.id} className="hover:bg-slate-800/30 transition-colors">
                    <td className="p-4 font-medium text-white min-w-[200px]">{item.name}</td>
                    <td className="p-4 text-slate-400 font-mono">{item.hsCode}</td>
                    <td className="p-4 text-right">
                      <input 
                        type="number" 
                        value={item.importCost} 
                        onChange={(e) => updateItem(item.id, 'importCost', e.target.value)}
                        className="bg-slate-900 border border-slate-700 rounded w-24 p-1 text-right text-white focus:border-cyan-500 outline-none"
                      />
                    </td>
                    <td className="p-4 text-right">
                      <input 
                        type="number" 
                        value={item.localCost} 
                        onChange={(e) => updateItem(item.id, 'localCost', e.target.value)}
                        className="bg-slate-900 border border-slate-700 rounded w-24 p-1 text-right text-white focus:border-cyan-500 outline-none"
                      />
                    </td>
                    <td className="p-4 text-center">
                      <button 
                        onClick={() => deleteItem(item.id)}
                        className="text-red-400 hover:text-red-300 transition-colors"
                      >
                        <span className="material-symbols-outlined text-sm">delete</span>
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="p-4 border-t border-slate-800 bg-slate-900/50">
            <button 
              onClick={addItem}
              className="text-cyan-400 text-sm flex items-center gap-2 hover:underline font-medium"
