            <div className="relative w-40 h-40 mx-auto flex items-center justify-center">
              <svg className="transform -rotate-90 w-full h-full">
                <circle cx="80" cy="80" r={radius} stroke="#1e293b" strokeWidth="12" fill="none"></circle>
                <circle 
                  cx="80" cy="80" r={radius} 
                  stroke={strokeColor} 
                  strokeWidth="12" 
                  fill="none" 
                  strokeDasharray={circumference} 
                  strokeDashoffset={offset}
                  className="transition-all duration-500 ease-out"
                ></circle>
              </svg>
              <span className={`absolute text-3xl font-mono font-bold ${statusColor}`}>
                {localContentPercent.toFixed(1)}%
              </span>
            </div>
          </div>

          <div className={`glass-panel p-4 rounded-xl border-l-4 ${statusBorder} transition-colors duration-300`}>
            <h3 className="font-bold text-lg text-white">{statusTitle}</h3>
            <p className="text-xs text-slate-400 mt-1">{statusDesc}</p>
            <div className="mt-3 flex gap-2">
              <span className={`px-2 py-1 bg-slate-800 ${statusColor.replace('text', 'text')} text-[10px] rounded border border-slate-700`}>MII Order 2017</span>
            </div>
          </div>

          <div className="glass-panel p-4 rounded-xl">
            <h4 className="text-sm font-semibold text-white mb-2">Sensitivity Analysis</h4>
            <div className="space-y-3">
              <div>
                <div className="flex justify-between text-xs text-slate-400 mb-1">
                  <span>If Import Costs Rise 10%</span>
                  <span className={`${localContentPercent < 55 ? 'text-red-400' : 'text-green-400'}`}>
                      {(localContentPercent - 0.4).toFixed(1)}% {localContentPercent < 50.4 ? '(Risk)' : '(Safe)'}
                  </span>
                </div>
                <div className="w-full bg-slate-700 h-1.5 rounded-full">
                  <div className={`${localContentPercent < 50.4 ? 'bg-red-500' : 'bg-green-500'} h-full rounded-full`} style={{ width: `${Math.min(localContentPercent - 0.4, 100)}%` }}></div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

