import React, { useState, useRef, useEffect } from 'react';
import { View } from '../types';

interface AnalyzerProps {
  onViewChange: (view: View) => void;
}

const Analyzer: React.FC<AnalyzerProps> = ({ onViewChange }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [selectedClauseId, setSelectedClauseId] = useState<string | null>(null);
  const [logs, setLogs] = useState<string[]>([]);
  const [riskScore, setRiskScore] = useState(0);
  const logsEndRef = useRef<HTMLDivElement>(null);

  // Risk Keywords
  const riskKeywords = ['violation', 'non-compliance', 'restrictive', 'monopoly', 'unclear', 'foreign', 'mandatory', 'exclude'];

  // Mock PDF Text content with hidden risks
  const pdfSections = [
    {
      id: 'clause-4.1',
      title: '4.1 Video Management System (VMS)',
      text: 'The VMS shall support ONVIF Profile S and G. It must be capable of handling 5000+ cameras concurrently.'
    },
    {
      id: 'clause-4.2',
      title: '4.2 Hosting Requirements (CRITICAL FLAG)',
      text: 'The proposed cloud solution must have a primary data center located in the United States or Europe. This is a restrictive condition creating a monopoly for foreign providers and implies non-compliance with data localization norms.',
      risky: true
    },
    {
      id: 'clause-4.3',
      title: '4.3 Analytics',
      text: 'The system must support facial recognition with 99% accuracy.'
    },
    {
      id: 'clause-4.4',
      title: '4.4 Hardware OEM',
      text: 'The OEM for cameras must have been operating in India for at least 10 years and have a turnover of $500M. This mandatory requirement is unclear and may exclude local MSMEs.'
    }
  ];

  // Auto-scroll logs
  useEffect(() => {
    if (logsEndRef.current) {
      logsEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [logs]);

  const addLog = (message: string) => {
    setLogs(prev => [...prev, message]);
  };

  const highlightText = (text: string) => {
    if (!selectedClauseId) return text; // Simple return if not analysing deep

    const parts = text.split(new RegExp(`(${riskKeywords.join('|')})`, 'gi'));
    return (
      <span>
        {parts.map((part, i) => 
          riskKeywords.some(k => k.toLowerCase() === part.toLowerCase()) ? (
            <span key={i} className="bg-red-500/30 text-red-200 px-0.5 rounded border-b border-red-500 animate-pulse font-semibold" title="Risk Keyword Detected">
              {part}
            </span>
          ) : (
            part
          )
        )}
      </span>
    );
  };

  const triggerScan = () => {
    setIsScanning(true);
    setLogs([]);
    setSelectedClauseId(null);
    setRiskScore(0);

    // Simulate AI Chain of Thought (The "Brain")
    setTimeout(() => addLog("> Initializing Sentinel OCR Engine..."), 100);
    setTimeout(() => addLog("> Uploading 'Nagpur_Smart_City_RFP.pdf' to Secure Enclave..."), 500);
    setTimeout(() => addLog("> Scanning for risk vectors: 'violation', 'monopoly', 'restrictive'..."), 1000);

    setTimeout(() => {
      // Calculate Risk Score based on keywords present in the mock text
      let foundRisks = 0;
      pdfSections.forEach(section => {
        riskKeywords.forEach(kw => {
           if (section.text.toLowerCase().includes(kw)) foundRisks++;
        });
      });
      setRiskScore(foundRisks * 15); // Arbitrary score calculation
      addLog(`> Semantic Analysis detected ${foundRisks} risk patterns.`);
    }, 1800);

    setTimeout(() => addLog("> Cross-referencing against Competitor DB (Hikvision, Honeywell)..."), 3200);
    setTimeout(() => addLog("> ALERT: Clause 4.2 violates DPDP Act 2023 Section 17"), 4000);

    setTimeout(() => {
      setIsScanning(false);
      addLog("> Scan Complete. 2 Critical Risks Found.");
      setSelectedClauseId('clause-4.2'); // Auto-select the kill shot
    }, 5000);
  };

  const handleClauseClick = (id: string) => {
    setSelectedClauseId(id);
    if(id === 'clause-4.2') {
        addLog(`> User focused Clause 4.2. Initiating deep legal retrieval...`);
    } else if (id === 'clause-4.4') {
        addLog(`> User focused Clause 4.4. Checking turnover thresholds...`);
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col fade-in">
      <div className="flex justify-between items-center">
        <div>
            <h2 className="text-2xl font-bold text-white">RFP Analyzer</h2>
            <p className="text-xs text-slate-400">Powered by <span className="text-cyan-400 font-mono">DeepSeek-R1</span> & <span className="text-cyan-400 font-mono">Pinecone</span></p>
        </div>
        <div className="flex items-center gap-4">
             {riskScore > 0 && (
                 <div className="flex items-center gap-2 px-3 py-1 rounded bg-red-900/30 border border-red-500/50">
                    <span className="text-xs text-red-400 font-mono uppercase">Risk Score</span>
                    <span className="text-lg font-bold text-white">{riskScore}/100</span>
                 </div>
             )}
            <button 
            className="bg-cyan-600 hover:bg-cyan-500 text-white px-4 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors shadow-lg shadow-cyan-900/50" 
            onClick={triggerScan}
            disabled={isScanning}
            >
            <span className="material-symbols-outlined text-sm">{isScanning ? 'hourglass_top' : 'upload_file'}</span>
            {isScanning ? 'Neural Scanning...' : 'Upload Tender PDF'}
            </button>
        </div>
      </div>

      <div className="grid grid-cols-12 gap-6 flex-1 min-h-0">
        {/* Left: Document Preview */}
        <div className={`col-span-12 lg:col-span-7 glass-panel rounded-xl overflow-hidden flex flex-col relative scanner-container ${isScanning ? 'scanning' : ''}`}>
