    setTimeout(() => addLog("> Parsing document structure (LayoutML)..."), 1200);
    setTimeout(() => addLog("> Neural Scanning for risk vectors: 'violation', 'monopoly', 'restrictive'..."), 1800);

    setTimeout(() => {
      // Calculate Risk Score based on keywords present in the mock text
