      pdfSections.forEach(section => {
        riskKeywords.forEach(kw => {
           if (section.text.toLowerCase().includes(kw)) foundRisks++;
        });
      });
      setRiskScore(foundRisks * 15);
      addLog(`> Semantic Analysis detected ${foundRisks} risk patterns.`);
    }, 2500);

    setTimeout(() => addLog("> Cross-referencing against Competitor DB (Hikvision, Honeywell)..."), 3500);
    setTimeout(() => addLog("> ALERT: Clause 4.2 violates DPDP Act 2023 Section 17"), 4200);

