    setSelectedClauseId(null);
    setRiskScore(0);

    // Realistic Processing Simulation
    let progress = 0;
    const interval = setInterval(() => {
        progress += Math.floor(Math.random() * 5) + 1;
        if (progress > 100) progress = 100;
        setScanProgress(progress);
    }, 150);

    setTimeout(() => addLog(`Initializing Sentinel OCR Engine v2.4...`), 100);
    setTimeout(() => addLog("Establishing secure enclave connection (AES-256)..."), 800);
    setTimeout(() => addLog("Extracting text layer and embedded metadata..."), 1500);
    setTimeout(() => addLog("Normalizing procurement terminology..."), 2200);
    setTimeout(() => addLog("Running Neural Risk Vector Analysis..."), 3000);

    setTimeout(() => {
      let foundRisks = 0;
      pdfSections.forEach(section => {
        riskKeywords.forEach(kw => {
           if (section.text.toLowerCase().includes(kw)) foundRisks++;
        });
      });
      setRiskScore(foundRisks * 15);
      addLog(`Semantic Analysis completed. Identified ${foundRisks} potential risk vectors.`);
    }, 4000);

    setTimeout(() => addLog("Cross-referencing GFR 2017 and CVC Guidelines..."), 4500);
    setTimeout(() => addLog("CRITICAL: Clause 4.2 flagged against DPDP Act 2023 Section 17"), 5200);

    setTimeout(() => {
      clearInterval(interval);
      setScanProgress(100);
      setIsScanning(false);
      setScanComplete(true);
      addLog("Report generated successfully.");
      setSelectedClauseId('clause-4.2'); 
    }, 5500);
  };

  return (
    <div className="space-y-6 h-full flex flex-col fade-in">
      {/* Top Header */}
      <div className="flex justify-between items-center bg-slate-900 border-b border-slate-700 pb-4">
        <div>
            <h2 className="text-2xl font-bold text-white font-header tracking-wide flex items-center gap-2">
              <span className="material-symbols-outlined text-blue-500">analytics</span>
              RFP ANALYZER
            </h2>
            <p className="text-xs text-slate-400 font-mono mt-1">SENTINEL INTELLIGENCE CORE // V2.0</p>
        </div>
        <div className="flex items-center gap-6">
             {riskScore > 0 && (
                 <div className="flex items-center gap-3 px-4 py-2 rounded border border-red-500/30 bg-red-900/10">
                    <span className="material-symbols-outlined text-red-500">warning</span>
                    <div className="text-right">
                      <p className="text-[10px] text-red-400 font-bold uppercase tracking-wider">Risk Index</p>
                      <p className="text-xl font-bold text-white leading-none font-header">{riskScore}/100</p>
                    </div>
                 </div>
             )}
        </div>
      </div>

      {/* Main Workspace */}
      <div className="grid grid-cols-12 gap-6 flex-1 min-h-0">

        {/* Left: Document Processing Unit */}
        <div className={`col-span-12 lg:col-span-7 glass-panel rounded-lg overflow-hidden flex flex-col relative scanner-container ${isScanning ? 'scanning' : ''}`}>

          {/* File Upload / Status Header */}
          <div className="bg-slate-800 p-4 border-b border-slate-700 flex justify-between items-center">
            {file ? (
              <div className="flex items-center gap-3 bg-slate-900 px-3 py-1.5 rounded border border-slate-700">
                <span className="material-symbols-outlined text-red-400">picture_as_pdf</span>
                <div>
                   <p className="text-sm font-medium text-white">{file.name}</p>
                   <p className="text-[10px] text-slate-400 uppercase tracking-wide">{(file.size / 1024 / 1024).toFixed(2)} MB • VERIFIED</p>
                </div>
                <button onClick={() => setFile(null)} className="ml-2 text-slate-500 hover:text-white">
                    <span className="material-symbols-outlined text-sm">close</span>
                </button>
              </div>
            ) : (
               <div className="flex items-center gap-2 text-slate-400 text-sm">
                   <span className="material-symbols-outlined">folder_off</span>
                   <span>No active document context</span>
               </div>
            )}

            <div className="flex gap-3">
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                accept="application/pdf" 
                className="hidden" 
              />
              {!file && (
                <button 
                  onClick={() => fileInputRef.current?.click()}
