    >
      {/* Toggle Button */}
      <button 
        onClick={() => setIsCollapsed(!isCollapsed)}
        className="absolute -right-3 top-8 bg-slate-800 border border-slate-600 text-slate-400 rounded-full p-1 hover:text-white transition-colors z-30 shadow-md"
      >
        <span className="material-symbols-outlined text-sm">
