        })}
      </nav>

      {/* Footer */}
      <div className={`p-4 border-t border-slate-800 ${isCollapsed ? 'flex justify-center' : ''} bg-slate-900`}>
        {!isCollapsed ? (
          <div className="bg-slate-800/50 rounded-sm p-3 text-xs border border-slate-700">
            <div className="flex items-center gap-2 mb-2 text-green-500">
              <span className="material-symbols-outlined text-sm">cloud_done</span>
              <span className="font-bold">Data Residency: OK</span>
