      due: '12 Days', 
      value: '₹25 Cr', 
      tag: 'RISK DETECTED', 
      tagColor: 'bg-red-500/10 text-red-400 border-red-500/20',
      risk: true
    },
    { 
      id: '2', 
      ref: 'CPPP/2025/DL/992', 
      title: 'Ruggedized Tablets for Border Roads Org', 
      due: '18 Days', 
      value: '₹8 Cr', 
      tag: 'HIGH FIT', 
      tagColor: 'bg-teal-500/10 text-teal-400 border-teal-500/20'
    },
    { 
      id: '3', 
      ref: 'GEM/2025/B/5510', 
      title: 'Data Center Hardware Refresh - NIC', 
      due: '5 Days', 
      value: '₹45 Cr', 
      tag: 'AMENDMENT', 
      tagColor: 'bg-gov-warning/10 text-gov-warning border-gov-warning/20'
    },
    { 
      id: '4', 
      ref: 'GEM/2025/B/1029', 
      title: 'Tactical Comms Upgrade', 
      due: '24 Days', 
      value: '₹110 Cr', 
      tag: 'REVIEWED', 
      tagColor: 'bg-slate-600/10 text-slate-400 border-slate-500/20'
    }
  ];

  // Filter Logic
  const filteredTenders = tenders.filter(t => 
    t.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    t.ref.toLowerCase().includes(searchTerm.toLowerCase()) ||
    t.tag.toLowerCase().includes(searchTerm.toLowerCase())
  );

  useEffect(() => {
    // Check if Leaflet is loaded
    const L = (window as any).L;
    if (!L || !mapContainerRef.current) return;

    // Initialize map if not already done
    if (!mapInstanceRef.current) {
      // Center on India
      const map = L.map(mapContainerRef.current, {
        zoomControl: false,
        attributionControl: true
      }).setView([22.5937, 78.9629], 5);

      mapInstanceRef.current = map;

      // Layer 1: Professional Dark Tiles
      L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>',
        subdomains: 'abcd',
        maxZoom: 19
      }).addTo(map);

      // Add Zoom Control at bottom right
      L.control.zoom({
        position: 'bottomright'
      }).addTo(map);

      // Define Custom Icons
      const createIcon = (color: string) => {
        return L.divIcon({
          className: 'custom-div-icon',
          html: `<div style="background-color: ${color}; width: 12px; height: 12px; border-radius: 50%; border: 2px solid #fff;"></div>`,
          iconSize: [12, 12],
          iconAnchor: [6, 6],
          popupAnchor: [0, -10]
        });
      };

      // Add Markers
      const locations = [
        { lat: 28.6139, lng: 77.2090, city: 'New Delhi', title: 'Smart City Survelliance', color: '#0FB7B3' }, // Teal
        { lat: 19.0760, lng: 72.8777, city: 'Mumbai', title: 'Naval Dockyard Upgrade', color: '#F6A623' }, // Warning
        { lat: 12.9716, lng: 77.5946, city: 'Bengaluru', title: 'Aerospace Components', color: '#A855F7' }, // Purple
        { lat: 21.1458, lng: 79.0882, city: 'Nagpur', title: 'Metro Rail Signalling', color: '#EF4444' } // Red
      ];

      locations.forEach(loc => {
        const marker = L.marker([loc.lat, loc.lng], { icon: createIcon(loc.color) }).addTo(map);

        const popupContent = `
          <div class="text-xs">
            <h4 class="font-bold text-white mb-1">${loc.city}</h4>
            <p class="text-slate-300 font-medium mb-1">${loc.title}</p>
            <button onclick="window.navigateToView('analyzer')" class="inline-block px-2 py-1 rounded bg-slate-700 hover:bg-slate-600 text-teal-400 cursor-pointer w-full text-left mt-2 font-semibold">
              Analyze Tender
            </button>
          </div>
        `;

        marker.bindPopup(popupContent);

        // Open popup on hover
        marker.on('mouseover', function (this: any) {
            this.openPopup();
        });
      });
    }

    // Cleanup on unmount
    return () => {
      if (mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
      }
    };
  }, []);

  return (
    <div className="space-y-6 fade-in h-full flex flex-col text-slate-200">
      {/* Metrics Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 flex-none">
        <div className="glass-panel p-4 rounded border-l-4 border-teal-500 relative overflow-hidden group">
