            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {filteredTenders.length === 0 ? (
              <div className="text-center text-slate-500 py-8 text-xs">
                No tenders found matching "{searchTerm}"
