  "parser_specs": {
    "cli_usage": "python parse_tender.py --input tender.pdf --output clauses.json",
    "clause_record_schema": {
      "tender_id": "UUID (Source Document ID)",
      "clause_id": "string (Generated: CL-{PageNum}-{SeqID})",
      "page_number": "integer",
      "char_range": {
