  "drafter_specs": {
    "prompts": {
      "concise": "ROLE: Legal Counsel (Concise Mode).\nTASK: Write a direct, bullet-pointed pre-bid query challenging the clause.\nRULES:\n1. Use < 100 words.\n2. Cite source immediately (e.g., 'Per GFR Rule 144...').\n3. No pleasantries. State the violation, Request amendment.",
      "formal": "ROLE: Senior Corporate Legal Head (Formal Mode).\nTASK: Draft a respectful but firm representation to the Tender Inviting Authority.\nRULES:\n1. Structure: Reference -> Observation -> Legal Ground -> Request.\n2. Use standard Gov-India correspondence etiquette.\n3. Cite specific Sections/Circulars.\n4. Goal: Compliance record creation.",
      "officer_friendly": "ROLE: Collaborative Partner (Officer Friendly Mode).\nTASK: Draft a query seeking clarification rather than confrontation.\nRULES:\n1. Phrase as a 'concern for wider participation'.\n2. 'We request the Authority to kindly verify alignment with [Source]...'\n3. Suggest the amendment as a way to improve competition."
    },
    "verifier_algorithm": "def verify_content(draft_text, source_docs):\n    # 1. Extraction: Parse citations from draft (Regex: 'Rule \\d+' | 'Section \\d+')\n    citations = extract_citations(draft_text)\n    \n    report = {'score': 1.0, 'flags': []}\n    \n    for cite in citations:\n        source_segment = find_source_segment(source_docs, cite.ref_id)\n        \n        # 2. Triple Verification Layer\n        # A. Exact Match (Character-for-character)\n        if cite.quoted_text in source_segment:\n            continue # Pass\n            \n        # B. Fuzzy Match (Levenshtein > 0.95)\n        ratio = fuzz.ratio(cite.quoted_text, source_segment)\n        if ratio >= 95:\n            continue # Pass\n            \n        # C. Sanity Rules (Semantic Check)\n        if check_meaning_distortion(cite.quoted_text, source_segment):\n             report['flags'].append(f\"DISTORTION: {cite.ref_id}\")\n             report['score'] -= 0.5\n        else:\n             report['flags'].append(f\"MISQUOTE: {cite.ref_id}\")\n             report['score'] -= 0.2\n             \n    if report['score'] < 0.8:\n        return HTTP_423_LOCKED(report)\n    return HTTP_200_OK(report)",
    "error_response_format": {
