  "l1_calculator": {
    "pseudocode": "def calculate_l1_status(bom_items, total_contract_value):\n    local_content_value = 0.0\n    \n    for item in bom_items:\n        # item: {unit_cost, quantity, local_percentage}\n        item_total = item.unit_cost * item.quantity\n        local_value = item_total * (item.local_percentage / 100.0)\n        local_content_value += local_value\n        \n    local_content_percent = (local_content_value / total_contract_value) * 100\n    \n    status = 'NON_LOCAL'\n    # Prefer >50.1 threshold for Class-I to avoid floating point ambiguity\n    if local_content_percent >= 50.1:\n        status = 'CLASS_I'\n    elif local_content_percent >= 20.0:\n        status = 'CLASS_II'\n        \n    return {\n        'local_value': local_content_value,\n        'percent': local_content_percent,\n        'status': status\n    }",
    "formula": "LC% = (Sum(ItemCost * Qty * ItemLocal%) / TotalContractValue) * 100",
