    "credential_generation": {
      "id_logic": "def generate_vendor_id(company_name):\n    # Extract first 3 consonants\n    consonants = re.sub(r'[aeiouAEIOU\\s\\W]', '', company_name).upper()[:3]\n    while len(consonants) < 3: consonants += 'X'\n    \n    # Generate 4 random digits\n    digits = str(secrets.randbelow(10000)).zfill(4)\n    \n    vendor_id = f'SB-{consonants}-{digits}'\n    \n    # Collision Handling\n    suffix = 'A'\n    while db.exists(vendor_id):\n        vendor_id = f'SB-{consonants}-{digits}-{suffix}'\n        suffix = chr(ord(suffix) + 1)\n        \n    return vendor_id",
      "password_logic": "def generate_secure_password():\n    # Entropy source > 60 bits\n    adjectives = load_wordlist('adjectives.txt') # 1000 words\n    syllables = load_wordlist('syllables.txt')   # 500 items\n    symbols = ['@', '#', '$', '%', '&', '*', '!']\n    \n    part1 = secrets.choice(adjectives).title()\n    part2 = str(secrets.randbelow(90) + 10) # 2 digits\n    part3 = secrets.choice(syllables)\n    part4 = secrets.choice(symbols)\n    \n    raw_password = f'{part1}{part2}{part3}{part4}'\n    \n    # IMMEDIATE HASHING - No Plaintext Storage\n    password_hash = argon2.hash(raw_password)\n    \n    return raw_password, password_hash"
    },
