  "l1_calculator": {
    "formula": "LC_Percent = (Sum(Item_Cost * Qty * (Item_Local_Pct / 100)) / Total_Contract_Value) * 100",
    "pseudocode": "def calculate_l1_status(bom_items, total_contract_value):\n    # 1. Aggregate Local Value\n    total_local_value = sum([item.cost * item.qty * (item.local_pct / 100.0) for item in bom_items])\n    \n    # 2. Calculate Percentage (Round to 2 decimal places to match Gov portal logic)\n    if total_contract_value <= 0: return {'status': 'ERROR', 'percent': 0.0}\n    \n    lc_percent = round((total_local_value / total_contract_value) * 100, 2)\n    \n    # 3. Classification with 50.1% Threshold (Class-I)\n    status = 'NON_LOCAL'\n    if lc_percent >= 50.1:\n        status = 'CLASS_I'\n    elif lc_percent >= 20.0:\n        status = 'CLASS_II'\n        \n    # 4. Tie-Breaker Logic\n    # If two bidders have same price, higher LC% wins.\n    # If LC% is also identical, higher absolute local value wins.\n    \n    return {\n        'local_value_abs': total_local_value,\n        'percent': lc_percent,\n        'status': status,\n        'tie_breaker_score': total_local_value\n    }",
    "sensitivity_routine": {
        "algorithm": "def get_sensitivity_ranking(bom_items):\n    # Identify items where increasing local content yields highest ROI\n    ranking = []\n    for item in bom_items:\n        # Impact = Total Cost of Item (Potential Local Value)\n        # Higher cost items with low current local content offer best optimization path\n        impact_score = (item.cost * item.qty) * (1.0 - (item.local_pct / 100.0))\n        ranking.append({'item_id': item.id, 'impact': impact_score})\n    \n    return sorted(ranking, key=lambda x: x['impact'], reverse=True)[:5]",
        "description": "Ranks top 5 BOM items by potential local value capture."
    },
