    "dev_mode_check": "func Authenticate(ctx *fiber.Ctx) error {\n    var creds LoginCredentials\n    if err := ctx.BodyParser(&creds); err != nil { return err }\n\n    env := os.Getenv(\"APP_ENV\")\n    if env == \"\" { env = \"production\" } // Default to Secure\n\n    // 1. DEVELOPER MODE SAFETY CHECK\n    if creds.Username == \"Sentinel_Developer\" {\n        if env == \"production\" {\n            // IMMUTABLE AUDIT LOG\n            AuditLog.Critical(\"SECURITY_VIOLATION\", \"Dev account attempted in PROD\", creds.Username)\n            // HARD STOP\n            return fiber.NewError(fiber.StatusForbidden, \"FATAL: Developer accounts are strictly prohibited in Production.\")\n        }\n        if creds.Password == \"sentineldev007\" {\n            return ctx.JSON(IssueStagingToken())\n        }\n    }\n\n    // 2. NORMAL FLOW\n    user := db.FindUser(creds.Username)\n    if !CheckHash(creds.Password, user.PasswordHash) {\n        return fiber.NewError(fiber.StatusUnauthorized, \"Invalid Credentials\")\n    }\n\n    // 3. 2FA ENFORCEMENT\n    if user.Role == \"Admin\" || user.Role == \"Legal-Auditor\" {\n        if !ValidateTOTP(user.Secret, creds.TotpCode) {\n            return fiber.NewError(fiber.StatusUnauthorized, \"2FA Token Required\")\n        }\n    }\n\n    return ctx.JSON(IssueJWT(user))\n}",
