  "parser_specs": {
    "cli_usage": "python parse_tender.py --input tender.pdf --output clauses.json",
    "clause_record_schema": {
      "tender_id": "UUID (Source Document ID)",
      "clause_id": "string (Generated: CL-{PageNum}-{SeqID})",
      "page_number": "integer",
      "char_range": {
        "start": "integer",
        "end": "integer"
      },
      "clause_text": "string (Cleaned content)",
      "text_hash": "string (SHA256 for integrity check)",
      "metadata": {
        "is_table": "boolean",
        "is_annexure": "boolean",
        "detected_header": "string (Optional)"
      }
    },
    "edge_case_rules": [
      {
        "case": "Header/Footer Noise",
        "action": "Filter text blocks located in top 5% and bottom 5% of page height if content is consistent >3 pages."
      },
      {
        "case": "Multi-Column Layout",
        "action": "Use PyMuPDF 'blocks' sort logic to read Left-Column Top-to-Bottom, then Right-Column."
      },
      {
        "case": "Scanned/Image PDF",
        "action": "If text_len < 50 chars/page, trigger Tesseract OCR via pdf2image."
      },
      {
        "case": "Tables spanning pages",
        "action": "Use pdfplumber to detect vertical grid lines; merge rows if bottom border is missing."
      }
    ],
    "unit_test_checklist": [
      "Test nested numbering (1.1 should not merge with 1.1.2)",
      "Test Annexure detection (Stop parsing clauses after 'Annexure A' or 'Section: Forms')",
      "Test Table extraction (Verify row count matches visual check)",
      "Test Multi-column re-flow (Ensure sentences aren't broken across columns)",
      "Test Zero-width characters (Strip hidden watermarks)"
    ],
    "parse_tender_py": "import argparse, json, hashlib, fitz, re, uuid\n\ndef parse_args():\n    parser = argparse.ArgumentParser(description=\"Sentinel PDF Parser\")\n    parser.add_argument(\"--input\", required=True, help=\"Input PDF path\")\n    parser.add_argument(\"--output\", required=True, help=\"Output JSON path\")\n    return parser.parse_args()\n\ndef generate_hash(text):\n    return hashlib.sha256(text.encode('utf-8')).hexdigest()\n\ndef extract_clauses(pdf_path):\n    doc = fitz.open(pdf_path)\n    clauses = []\n    tender_id = str(uuid.uuid4())\n    clause_pattern = re.compile(r'(^\\d+(\\.\\d+)+|Section\\s+[IVX]+)', re.MULTILINE)\n    \n    for page_num, page in enumerate(doc):\n        blocks = page.get_text(\"blocks\") # Respects layout\n        blocks.sort(key=lambda b: (b[1], b[0])) # Top-down, Left-right\n        \n        for b in blocks:\n            text = b[4].strip()\n            if len(text) < 5 or \"Page\" in text: continue # Skip noise\n            \n            if clause_pattern.match(text) or len(clauses) == 0:\n                clauses.append({\n                    \"tender_id\": tender_id,\n                    \"clause_id\": f\"CL-PG{page_num+1}-{len(clauses)}\",\n                    \"page\": page_num + 1,\n                    \"char_range\": {\"start\": 0, \"end\": len(text)},\n                    \"clause_text\": text,\n                    \"text_hash\": generate_hash(text)\n                })\n            else:\n                # Append to previous if not a new clause header (Naive)\n                prev = clauses[-1]\n                prev['clause_text'] += \" \" + text\n                prev['char_range']['end'] = len(prev['clause_text'])\n                prev['text_hash'] = generate_hash(prev['clause_text'])\n    return clauses\n\nif __name__ == \"__main__\":\n    args = parse_args()\n    data = extract_clauses(args.input)\n    with open(args.output, 'w') as f:\n        json.dump(data, f, indent=2)",
    "dockerfile": "FROM python:3.9-slim-buster\n\n# System dependencies for OCR and Image processing\nRUN apt-get update && apt-get install -y \\\n    tesseract-ocr \\\n    libpoppler-cpp-dev \\\n    gcc \\\n    ffmpeg libsm6 libxext6 \\\n    && rm -rf /var/lib/apt/lists/*\n\nWORKDIR /app\n\n# Python dependencies\n# Create requirements.txt inline or copy\nRUN echo \"pymupdf==1.23.8\\npdfplumber==0.10.3\\npytesseract==0.3.10\\nrapidfuzz==3.5.2\" > requirements.txt\nRUN pip install --no-cache-dir -r requirements.txt\n\nCOPY parse_tender.py .\n\nENTRYPOINT [\"python\", \"parse_tender.py\"]"
  },
