    "approve_flow": {
      "workflow_logic": "func Approve(ctx, ticketID, totp) {\n  user := ctx.User\n  if !ValidateTOTP(user.Secret, totp) { return 403_INVALID_2FA }\n  \n  draft := db.GetDraft(ticketID)\n  // Generate Immutable Signature\n  payload := draft.Hash + user.ID + Now()\n  signature := SHA256(payload)\n  \n  db.Update(ticketID, {\n    'status': 'APPROVED',\n    'approver_id': user.ID,\n    'approval_signature': signature,\n    'approved_at': Now()\n  })\n  \n  AuditLog.Log('LEGAL_SIGN_OFF', user.ID, ticketID, signature)\n}"
    },
