      "check_pseudocode": "func GenerateExport(ticketID) {\n  draft := db.GetDraft(ticketID)\n  \n  // EXPORT LOCK\n  if draft.Status != 'APPROVED' || draft.ApprovalSignature == '' {\n     return HTTP_403('EXPORT_LOCKED: Legal Approval Required')\n  }\n  \n  return CreateEvidencePackage(draft)\n}"
    },
