  "infra_ci_specs": {
    "terraform_skeleton": {
      "provider": "aws",
      "region": "ap-south-1 (Mumbai) - STRICT DATA RESIDENCY",
      "main_tf": "terraform {\n  required_version = \">= 1.5.0\"\n  backend \"s3\" {\n    bucket         = \"sentinel-terraform-state-prod\"\n    key            = \"platform/terraform.tfstate\"\n    region         = \"ap-south-1\"\n    encrypt        = true\n    dynamodb_table = \"sentinel-lock-table\"\n  }\n  required_providers {\n    aws = { source = \"hashicorp/aws\", version = \"~> 5.0\" }\n  }\n}\n\nprovider \"aws\" {\n  region = \"ap-south-1\"\n  default_tags {\n    tags = {\n      Project     = \"Sentinel-Bharat\"\n      Environment = \"Production\"\n      Compliance  = \"Data-Residency-India\"\n    }\n  }\n}\n\n# KMS for Envelope Encryption\nresource \"aws_kms_key\" \"sentinel_key\" {\n  description             = \"Sentinel Application Master Key\"\n  deletion_window_in_days = 30\n  enable_key_rotation     = true\n}",
      "vpc_tf": "module \"vpc\" {\n  source = \"terraform-aws-modules/vpc/aws\"\n  name   = \"sentinel-vpc-prod\"\n  cidr   = \"10.0.0.0/16\"\n  azs    = [\"ap-south-1a\", \"ap-south-1b\"]\n  private_subnets = [\"10.0.1.0/24\", \"10.0.2.0/24\"]\n  public_subnets  = [\"10.0.101.0/24\", \"10.0.102.0/24\"]\n  enable_nat_gateway = true\n  enable_vpn_gateway = false\n}",
      "eks_tf": "module \"eks\" {\n  source  = \"terraform-aws-modules/eks/aws\"\n  cluster_name    = \"sentinel-cluster-prod\"\n  cluster_version = \"1.28\"\n  subnet_ids      = module.vpc.private_subnets\n  vpc_id          = module.vpc.vpc_id\n  eks_managed_node_groups = {\n    general = {\n      min_size     = 2\n      max_size     = 5\n      desired_size = 2\n      instance_types = [\"t3.xlarge\"]\n    }\n    ai_inference = {\n      min_size = 1\n      instance_types = [\"g4dn.xlarge\"] # GPU for RAG/OCR\n      labels = { \"workload\" = \"ai-core\" }\n      taints = [{ key = \"workload\", value = \"ai-core\", effect = \"NO_SCHEDULE\" }]\n    }\n  }\n}",
      "rds_tf": "resource \"aws_db_instance\" \"sentinel_db\" {\n  identifier           = \"sentinel-pg-prod\"\n  engine               = \"postgres\"\n  engine_version       = \"15.4\"\n  instance_class       = \"db.t3.medium\"\n  allocated_storage    = 50\n  storage_encrypted    = true\n  kms_key_id           = aws_kms_key.sentinel_key.arn\n  multi_az             = true\n  db_name              = \"sentinel_core\"\n  username             = var.db_username\n  password             = var.db_password\n  skip_final_snapshot  = false\n}",
      "s3_tf": "resource \"aws_s3_bucket\" \"evidence_vault\" {\n  bucket = \"sentinel-evidence-vault-prod-ap-south-1\"\n}\nresource \"aws_s3_bucket_server_side_encryption_configuration\" \"vault_enc\" {\n  bucket = aws_s3_bucket.evidence_vault.id\n  rule {\n    apply_server_side_encryption_by_default {\n      kms_master_key_id = aws_kms_key.sentinel_key.arn\n      sse_algorithm     = \"aws:kms\"\n    }\n  }\n}"
    },
    "github_actions_workflow": "name: Sentinel CI/CD Pipeline\n\non:\n  push:\n    branches: [ \"main\" ]\n  pull_request:\n    branches: [ \"main\" ]\n\njobs:\n  security-audit:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v3\n      - name: Run Trivy Vulnerability Scanner\n        uses: aquasecurity/trivy-action@master\n        with:\n          scan-type: 'fs'\n          ignore-unfixed: true\n          severity: 'CRITICAL,HIGH'\n\n  test-and-build:\n    needs: security-audit\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v3\n      \n      # Backend Go\n      - name: Test Backend (Go)\n        working-directory: ./backend\n        run: |\n          go test -v ./...\n      \n      # AI Python\n      - name: Test AI Core (Python)\n        working-directory: ./ai\n        run: |\n          pip install -r requirements.txt\n          pytest\n\n      # Build & Push Docker\n      - name: Configure AWS Credentials\n        uses: aws-actions/configure-aws-credentials@v1\n        with:\n          aws-access-key-id: ${{ secrets.AWS_ACCESS_KEY_ID }}\n          aws-secret-access-key: ${{ secrets.AWS_SECRET_ACCESS_KEY }}\n          aws-region: ap-south-1\n\n      - name: Login to ECR\n        uses: aws-actions/amazon-ecr-login@v1\n      \n      - name: Build and Push Backend\n        run: |\n          docker build -t $ECR_REGISTRY/sentinel-backend:$GITHUB_SHA ./backend\n          docker push $ECR_REGISTRY/sentinel-backend:$GITHUB_SHA\n\n  deploy-plan:\n    needs: test-and-build\n    runs-on: ubuntu-latest\n    steps:\n      - uses: hashicorp/setup-terraform@v2\n      - run: terraform plan",
    "gitops_manifests": {
      "argocd_app": "apiVersion: argoproj.io/v1alpha1\nkind: Application\nmetadata:\n  name: sentinel-bharat-prod\n  namespace: argocd\nspec:\n  project: default\n  source:\n    repoURL: 'https://github.com/gov-india/sentinel-bharat.git'\n    targetRevision: HEAD\n    path: infra/k8s/overlays/prod\n  destination:\n    server: 'https://kubernetes.default.svc'\n    namespace: sentinel-prod\n  syncPolicy:\n    automated:\n      prune: true\n      selfHeal: true",
      "deployment_yaml": "apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: sentinel-backend\n  namespace: sentinel-prod\nspec:\n  replicas: 3\n  selector:\n    matchLabels:\n      app: sentinel-backend\n  template:\n    metadata:\n      labels:\n        app: sentinel-backend\n    spec:\n      containers:\n      - name: backend\n        image: 123456789012.dkr.ecr.ap-south-1.amazonaws.com/sentinel-backend:latest\n        ports:\n        - containerPort: 8080\n        env:\n        - name: DB_HOST\n          valueFrom:\n            secretKeyRef:\n              name: db-secrets\n              key: host"
    }
