        "snippet": "func TestCalculateL1Status_EdgeCases(t *testing.T) {\n    // Case: Exactly 50.0% -> Should be Non-Class-I (Strict > 50% or >=50% depending on exact policy, usually >=50)\n    // Let's assume policy is >= 50%\n    items := []Item{{Cost: 100, LocalPct: 50}}\n    res := CalculateL1(items)\n    if res.Status != \"CLASS_I\" { t.Errorf(\"Expected CLASS_I for 50%%, got %s\", res.Status) }\n\n    // Case: Zero Value Contract\n    itemsZero := []Item{}\n    resZero := CalculateL1(itemsZero)\n    if resZero.Status != \"ERROR\" { t.Error(\"Expected ERROR for zero items\") }\n}"
