                 <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse delay-75" title="CPPP XML: Connected"></div>
                 <div className="w-2 h-2 rounded-full bg-slate-600" title="Manual: Idle"></div>
             </div>
          </div>

          {/* Filter Controls */}
