    { id: View.VAULT, label: 'Evidence Vault', icon: 'folder_managed' },
  ];

  return (
    <aside 
      className={`${isCollapsed ? 'w-20' : 'w-64'} bg-primary border-r border-white/10 flex flex-col z-20 shrink-0 transition-all duration-300 ease-in-out relative shadow-lg text-white`}
    >
      {/* Toggle Button */}
      <button 
        onClick={() => setIsCollapsed(!isCollapsed)}
        className="absolute -right-3 top-8 bg-surface-2 border border-gray-200 text-gray-500 rounded-full p-1 hover:text-primary transition-colors z-30 shadow-md"
      >
        <span className="material-symbols-outlined text-sm">
          {isCollapsed ? 'chevron_right' : 'chevron_left'}
        </span>
      </button>

      {/* Header */}
      <div className={`p-4 flex items-center gap-3 border-b border-white/10 h-16 ${isCollapsed ? 'justify-center' : ''} bg-primary`}>
        <div className="w-8 h-8 bg-accent rounded flex items-center justify-center shadow-md shrink-0">
          <span className="material-symbols-outlined text-white text-lg">shield_lock</span>
        </div>
        {!isCollapsed && (
          <div className="overflow-hidden whitespace-nowrap flex items-baseline gap-1.5">
            <span className="text-xl text-white leading-none" style={{ fontFamily: '"Times New Roman", serif', fontWeight: 'bold' }}>RK</span>
            <span className="font-semibold text-lg tracking-wide text-white font-header uppercase leading-none">Sentinel</span>
            <span className="text-sm text-accent font-light italic tracking-wider leading-none">Prime</span>
          </div>
        )}
      </div>

      {/* Nav Items */}
      <nav className="flex-1 p-3 space-y-1 mt-2">
        {navItems.map((item) => {
          const isActive = currentView === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onViewChange(item.id)}
              title={isCollapsed ? item.label : ''}
              className={`w-full flex items-center gap-3 px-3 py-3 rounded transition-all ${
                isActive
                  ? 'bg-white/10 text-accent border-l-4 border-accent font-medium'
                  : 'text-gray-200 hover:text-white hover:bg-white/5 border-l-4 border-transparent'
              } ${isCollapsed ? 'justify-center' : ''}`}
            >
              <span className={`material-symbols-outlined text-xl ${isActive ? 'text-accent' : 'text-gray-400'}`}>{item.icon}</span>
              {!isCollapsed && <span className="font-medium whitespace-nowrap text-sm">{item.label}</span>}
            </button>
          );
        })}
      </nav>

      {/* Footer */}
      <div className={`p-4 border-t border-white/10 ${isCollapsed ? 'flex justify-center' : ''} bg-primary`}>
        {!isCollapsed ? (
          <div className="bg-black/20 rounded p-3 text-xs border border-white/5">
            <div className="flex items-center gap-2 mb-2 text-accent">
              <span className="material-symbols-outlined text-sm">cloud_done</span>
              <span className="font-bold">ap-south-1</span>
            </div>
            <p className="text-gray-400 font-mono">ENCRYPTION: AES-256</p>
          </div>
        ) : (
          <div className="w-8 h-8 rounded-full bg-black/20 border border-white/5 flex items-center justify-center" title="System Secure">
             <span className="material-symbols-outlined text-accent text-sm">cloud_done</span>
          </div>
        )}
      </div>
    </aside>
  );
};

