import Vault from './Vault';
import Login from './Login';
import Onboarding from './Onboarding';
import VerificationModal from './VerificationModal';
import LegalGateModal from './LegalGateModal';

// Extend window interface for map popup navigation
declare global {
  interface Window {
    navigateToView: (viewName: string) => void;
  }
}

export default function App() {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState(false);

  // Expose navigation to window for Leaflet popups
  useEffect(() => {
    window.navigateToView = (viewName: string) => {
      if (Object.values(View).includes(viewName as View)) {
        setCurrentView(viewName as View);
      }
    };
  }, []);

  const handleLogin = (user: User) => {
      setCurrentUser(user);
      // Simulate first-time login check
      if (user.name === 'New Vendor') {
          setShowOnboarding(true);
      } else {
          setCurrentView(View.DASHBOARD);
      }
  };

  const handleOnboardingComplete = () => {
      setShowOnboarding(false);
      setCurrentView(View.DASHBOARD);
  };

  // SVG User Profile Base64
  const userProfileSvg = `data:image/svg+xml;base64,`;

  const renderView = () => {
    if (showOnboarding) {
        return <Onboarding onComplete={handleOnboardingComplete} />;
    }
    switch (currentView) {
      case View.DASHBOARD:
        return <Dashboard onViewChange={setCurrentView} />;
      case View.ANALYZER:
        return <Analyzer onViewChange={setCurrentView} />;
      case View.PREBID:
        return <PreBidStudio onViewChange={setCurrentView} onOpenModal={() => setIsModalOpen(true)} />;
      case View.CALCULATOR:
        return <Calculator />;
      case View.VAULT:
        return <Vault />;
      case View.ONBOARDING:
        return <Onboarding onComplete={handleOnboardingComplete} />;
      default:
        return <Dashboard onViewChange={setCurrentView} />;
    }
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex h-screen overflow-hidden text-sm bg-surface text-gray-900 font-inter">
      {/* Sidebar */}
      {!showOnboarding && <Sidebar currentView={currentView} onViewChange={setCurrentView} />}

      {/* Main Content */}
      <main className="flex-1 flex flex-col relative bg-surface">
        {/* Header */}
        {!showOnboarding && (
            <header className="h-16 border-b border-gray-200 flex items-center justify-between px-6 bg-surface-2 sticky top-0 z-10 shrink-0">
            <div className="flex items-center gap-4">
                <span className="px-2 py-1 bg-warning/10 text-warning text-xs font-mono rounded border border-warning/20 animate-pulse flex items-center gap-2 font-bold">
                <span className="w-2 h-2 rounded-full bg-warning"></span>
                LIVE FEED ACTIVE
                </span>
                <span className="text-gray-500 text-xs hidden sm:inline">
                Last Sync: <span className="font-mono text-primary font-medium">14:02:45 IST</span>
                </span>
                <span className="text-[10px] text-gray-400 font-mono hidden lg:block border border-gray-200 px-2 py-0.5 rounded">
                AI MODEL: SENTINEL-CORE-V2
                </span>
            </div>
            <div className="flex items-center gap-4">
                <button className="p-2 text-gray-400 hover:text-primary relative transition-colors">
                <span className="material-symbols-outlined">notifications</span>
                <span className="absolute top-2 right-2 w-2 h-2 bg-danger rounded-full animate-ping"></span>
                <span className="absolute top-2 right-2 w-2 h-2 bg-danger rounded-full"></span>
                </button>
                <div className="flex items-center gap-3 pl-4 border-l border-gray-200">
                <div className="text-right hidden sm:block">
                    <p className="text-gray-900 font-bold text-xs">{currentUser.name}</p>
                    <p className="text-[10px] text-primary font-mono">{currentUser.designation}</p>
                </div>
                <div className="w-9 h-9 rounded-full bg-gray-200 p-0.5 border border-gray-300 overflow-hidden">
                    <img alt="User" className="w-full h-full object-cover rounded-full" src={userProfileSvg} />
                </div>
                </div>
            </div>
            </header>
        )}

        {/* View Container */}
        <div className="flex-1 overflow-y-auto overflow-x-hidden p-6 relative">
          {renderView()}
        </div>
      </main>

      {/* Modal */}
      <VerificationModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
    </div>
  );
}

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'accent' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  icon?: string;
}

export const Button: React.FC<ButtonProps> = ({ 
  variant = 'primary', 
  size = 'md', 
  icon, 
  children, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center font-bold rounded transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-primary text-white hover:bg-[#082846] focus:ring-primary",
    secondary: "bg-white text-gray-700 border border-gray-300 hover:bg-gray-50 focus:ring-gray-300",
    accent: "bg-accent text-white hover:bg-[#0B9487] focus:ring-accent",
    danger: "bg-danger text-white hover:bg-[#C93636] focus:ring-danger",
  };

  const sizes = {
    sm: "px-3 py-1.5 text-xs",
    md: "px-4 py-2 text-sm",
    lg: "px-6 py-3 text-base",
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {icon && <span className="material-symbols-outlined mr-2 text-lg">{icon}</span>}
      {children}
    </button>
  );
};

