      title: '4.4 Hardware OEM',
      text: 'The OEM for cameras must have been operating in India for at least 10 years and have a turnover of $500M. This mandatory requirement is unclear and may exclude local MSMEs.'
    }
  ];

  // Auto-scroll logs
  useEffect(() => {
    if (logsEndRef.current) {
      logsEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [logs]);

  const addLog = (message: string) => {
    const timestamp = new Date().toISOString().split('T')[1].slice(0, 8);
    setLogs(prev => [...prev, `[${timestamp}] ${message}`]);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const selectedFile = e.target.files[0];
      if (selectedFile.type !== 'application/pdf') {
        alert("System Protocol Error: Only PDF documents are accepted for parsing.");
        return;
      }
      setFile(selectedFile);
      setScanComplete(false);
      setRiskScore(0);
      setLogs([]);
      addLog(`Secure File Mount: ${selectedFile.name}`);
      addLog(`Size: ${(selectedFile.size / 1024).toFixed(2)} KB | Type: application/pdf`);
      addLog("Ready for deep inspection.");
    }
  };

  const highlightText = (text: string) => {
    if (!selectedClauseId) return text; 

    const parts = text.split(new RegExp(`(${riskKeywords.join('|')})`, 'gi'));
    return (
      <span>
        {parts.map((part, i) => 
          riskKeywords.some(k => k.toLowerCase() === part.toLowerCase()) ? (
            <span key={i} className="bg-danger/10 text-danger px-1 rounded border-b border-danger font-semibold" title="Risk Pattern Detected">
              {part}
            </span>
          ) : (
            part
          )
        )}
      </span>
    );
  };

  const triggerScan = () => {
    if (!file) return;

    setIsScanning(true);
    setScanProgress(0);
    setLogs([]);
    setSelectedClauseId(null);
    setRiskScore(0);

    let progress = 0;
    const interval = setInterval(() => {
        progress += Math.floor(Math.random() * 5) + 1;
        if (progress > 100) progress = 100;
        setScanProgress(progress);
    }, 150);

    setTimeout(() => addLog(`Initializing Sentinel OCR Engine v2.4...`), 100);
    setTimeout(() => addLog("Establishing secure enclave connection (AES-256)..."), 800);
    setTimeout(() => addLog("Extracting text layer and embedded metadata..."), 1500);
    setTimeout(() => {
      let foundRisks = 0;
      pdfSections.forEach(section => {
        riskKeywords.forEach(kw => {
           if (section.text.toLowerCase().includes(kw)) foundRisks++;
        });
      });
      setRiskScore(foundRisks * 15);
      addLog(`Semantic Analysis completed. Identified ${foundRisks} potential risk vectors.`);
    }, 4000);

    setTimeout(() => {
      clearInterval(interval);
      setScanProgress(100);
      setIsScanning(false);
      setScanComplete(true);
      addLog("Report generated successfully.");
      setSelectedClauseId('clause-4.2'); 
    }, 5500);
  };

  const handleClauseClick = (id: string) => {
    setSelectedClauseId(id);
  };

  return (
    <div className="space-y-6 h-full flex flex-col fade-in text-gray-900">
      {/* Top Header */}
      <div className="flex justify-between items-center bg-surface-2 border-b border-gray-200 pb-4">
        <div>
            <h2 className="text-2xl font-bold text-primary font-header tracking-wide flex items-center gap-2">
              <span className="material-symbols-outlined text-primary">analytics</span>
              RFP ANALYZER
            </h2>
            <p className="text-xs text-gray-500 font-mono mt-1">SENTINEL INTELLIGENCE CORE // V2.0</p>
        </div>
        <div className="flex items-center gap-6">
             {riskScore > 0 && (
                 <div className="flex items-center gap-3 px-4 py-2 rounded border border-danger/30 bg-danger/10">
                    <span className="material-symbols-outlined text-danger">warning</span>
                    <div className="text-right">
                      <p className="text-[10px] text-danger font-bold uppercase tracking-wider">Risk Index</p>
                      <p className="text-xl font-bold text-gray-900 leading-none font-header">{riskScore}/100</p>
                    </div>
                 </div>
             )}
        </div>
      </div>

      {/* Main Workspace */}
      <div className="grid grid-cols-12 gap-6 flex-1 min-h-0">

        {/* Left: Document Processing Unit */}
        <div className={`col-span-12 lg:col-span-7 glass-panel rounded-lg overflow-hidden flex flex-col relative scanner-container ${isScanning ? 'scanning' : ''}`}>

          {/* File Upload / Status Header */}
          <div className="bg-surface-2 p-4 border-b border-gray-200 flex justify-between items-center">
            {file ? (
              <div className="flex items-center gap-3 bg-gray-50 px-3 py-1.5 rounded border border-gray-200">
                <span className="material-symbols-outlined text-danger">picture_as_pdf</span>
                <div>
                   <p className="text-sm font-medium text-gray-900">{file.name}</p>
                   <p className="text-[10px] text-gray-500 uppercase tracking-wide">{(file.size / 1024 / 1024).toFixed(2)} MB • VERIFIED</p>
                </div>
                <button onClick={() => setFile(null)} className="ml-2 text-gray-400 hover:text-danger">
                    <span className="material-symbols-outlined text-sm">close</span>
                </button>
              </div>
            ) : (
               <div className="flex items-center gap-2 text-gray-400 text-sm">
                   <span className="material-symbols-outlined">folder_off</span>
                   <span>No active document context</span>
               </div>
            )}

            <div className="flex gap-3">
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                accept="application/pdf" 
                className="hidden" 
              />
              {!file && (
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="bg-white hover:bg-gray-50 text-gray-700 px-4 py-2 rounded-sm text-xs font-medium border border-gray-300 transition-colors flex items-center gap-2 shadow-sm"
                >
                  <span className="material-symbols-outlined text-sm">upload_file</span>
                  UPLOAD RFP
                </button>
              )}

              <button 
                className={`px-5 py-2 rounded-sm text-xs font-bold uppercase tracking-wider transition-all flex items-center gap-2 ${
                  !file || isScanning 
                    ? 'bg-gray-200 text-gray-400 cursor-not-allowed border border-gray-300' 
                    : 'bg-primary hover:bg-navy-800 text-white shadow-md border border-primary'
                }`}
                onClick={triggerScan}
                disabled={!file || isScanning}
              >
                {isScanning ? (
                  <>SCANNING {(scanProgress).toFixed(0)}%</>
                ) : (
                  <>INITIATE SCAN</>
                )}
              </button>
            </div>
          </div>

          <div className="scanner-line"></div>

          {/* Document Viewer Area */}
          <div className="flex-1 bg-white text-gray-900 font-serif text-sm overflow-y-auto relative selection:bg-blue-200 p-8 shadow-inner">
            {!file ? (
              <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-70">
                 <div className="w-20 h-20 border-2 border-dashed border-gray-300 rounded-lg flex items-center justify-center mb-4">
                    <span className="material-symbols-outlined text-4xl">cloud_upload</span>
                 </div>
                 <p className="text-lg font-sans font-semibold text-gray-600">Upload Tender Document</p>
                 <p className="text-xs mt-1 font-mono">SECURE UPLOAD // PDF FORMAT ONLY</p>
              </div>
            ) : !scanComplete && !isScanning ? (
               <div className="h-full flex flex-col items-center justify-center fade-in">
                  <div className="w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mb-4 border border-blue-100">
                    <span className="material-symbols-outlined text-3xl text-primary">visibility</span>
                  </div>
                  <p className="text-gray-700 font-sans font-bold text-lg">Document Preview Locked</p>
                  <p className="text-xs text-gray-500 mt-2 font-mono bg-white px-2 py-1 rounded border border-gray-200">
                      WAITING FOR NEURAL ANALYSIS
                  </p>
               </div>
            ) : (
              // Content Rendering
              <div className="max-w-3xl mx-auto space-y-6 animate-in fade-in duration-500">
                <div className="flex justify-between items-end border-b-2 border-gray-200 pb-4 mb-8">
                  <div>
                    <h1 className="text-xl font-bold uppercase tracking-wide font-header text-gray-900">Request For Proposal</h1>
                    <p className="text-xs text-gray-500 mt-1 font-mono">REF: {file.name.toUpperCase().replace('.PDF', '')}</p>
                  </div>
                  <div className="text-right">
                      <p className="text-[10px] uppercase font-bold text-gray-400">Classification</p>
                      <p className="text-sm font-bold text-gray-900">PUBLIC / OPEN TENDER</p>
                  </div>
                </div>

                <p className="font-bold text-lg border-b pb-2 border-gray-300 text-gray-800 font-header">SECTION IV: TECHNICAL SPECIFICATIONS</p>

                {pdfSections.map((section) => (
                  <div 
                      key={section.id}
                      className={`p-4 rounded-sm transition-all duration-200 border-l-4 ${
                          selectedClauseId === section.id 
                              ? section.id.includes('4.2') || section.id.includes('4.4') 
                                  ? 'border-l-danger bg-red-50 ring-1 ring-red-100 shadow-sm'
                                  : 'border-l-primary bg-blue-50 ring-1 ring-blue-100 shadow-sm' 
                              : 'border-l-transparent hover:bg-gray-50'
                      } ${section.risky && !selectedClauseId ? 'bg-red-50/50' : ''} cursor-pointer group`}
                      onClick={() => handleClauseClick(section.id)}
                  >
                      <div className="flex justify-between mb-1">
                          <span className="font-bold block text-gray-800 group-hover:text-primary">{section.title}</span>
                          {section.risky && <span className="text-[10px] font-bold bg-danger/10 text-danger px-1.5 py-0.5 rounded border border-danger/20">RISK DETECTED</span>}
                      </div>
                      <span className="leading-relaxed text-gray-700">
                          {highlightText(section.text)}
                      </span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Right: Intelligence Panel */}
        <div className="col-span-12 lg:col-span-5 flex flex-col gap-4">

          {/* Analysis Results */}
          <div className="glass-panel p-0 rounded-lg flex-1 flex flex-col min-h-[300px] overflow-hidden border-gray-300">
            <div className="p-3 border-b border-gray-200 bg-surface-2 flex justify-between items-center">
               <h3 className="font-semibold text-primary font-header flex items-center gap-2">
                 <span className="material-symbols-outlined text-primary text-lg">psychology</span>
                 TACTICAL INSIGHTS
               </h3>
               {selectedClauseId && (
                   <button onClick={() => setSelectedClauseId(null)} className="text-[10px] text-gray-500 hover:text-primary uppercase font-bold">Clear Selection</button>
               )}
            </div>

            <div className="p-4 flex-1 overflow-y-auto bg-surface">
              {!selectedClauseId ? (
                <div className="h-full flex flex-col items-center justify-center text-gray-400">
                  <span className="material-symbols-outlined text-4xl mb-3 opacity-30">touch_app</span>
                  <p className="text-sm font-medium">Select a clause to view analysis</p>
                </div>
              ) : (
                selectedClauseId === 'clause-4.2' ? (
                  <div className="space-y-4 fade-in">
                    <div className="p-4 bg-white border border-danger/30 rounded-sm relative overflow-hidden shadow-sm">
                      <div className="flex justify-between items-start mb-2 relative z-10">
                        <h4 className="text-danger font-bold flex items-center gap-2 font-header text-lg">
                          <span className="material-symbols-outlined text-sm">gavel</span>
                          Data Residency Violation
                        </h4>
                        <span className="text-[10px] font-bold bg-danger text-white px-2 py-0.5 rounded-sm tracking-wide">CONFIDENCE: 98%</span>
                      </div>
                      <p className="text-gray-600 text-sm mt-2 leading-relaxed relative z-10 border-t border-danger/10 pt-2">
                        The clause mandates foreign hosting (US/EU/Singapore). This explicitly violates <strong>MeitY Guidelines</strong> and the <strong>DPDP Act 2023</strong> regarding sensitive citizen data.
                      </p>
                    </div>

                    <div className="space-y-3">
                      <p className="text-[10px] text-gray-500 uppercase font-bold tracking-widest border-b border-gray-200 pb-1">Legal Precedents (RAG)</p>
                      <div className="flex items-start gap-3 p-3 bg-white rounded-sm border border-gray-200 hover:border-gray-300 transition-colors shadow-sm">
                        <span className="material-symbols-outlined text-warning text-lg mt-0.5">book_2</span>
                        <div className="text-xs">
                          <p className="text-gray-900 font-semibold">DPDP Act 2023</p>
                          <p className="text-gray-500 mt-0.5">Section 17: Restrictions on Cross-border data transfer.</p>
                        </div>
                      </div>
                      <div className="flex items-start gap-3 p-3 bg-white rounded-sm border border-gray-200 hover:border-gray-300 transition-colors shadow-sm">
                        <span className="material-symbols-outlined text-accent text-lg mt-0.5">cloud_done</span>
                        <div className="text-xs">
                          <p className="text-gray-900 font-semibold">MeitY Cloud Empanelment</p>
                          <p className="text-gray-500 mt-0.5">Mandatory in-country hosting for Govt Data.</p>
                        </div>
                      </div>
                    </div>

                    <div className="mt-4 pt-4 border-t border-gray-200">
                      <button 
                        className="w-full bg-primary hover:bg-navy-800 text-white py-3 rounded-sm font-bold text-sm uppercase tracking-wide flex items-center justify-center gap-2 transition-all shadow-md"
                        onClick={() => onViewChange(View.PREBID)}
                      >
                        <span className="material-symbols-outlined text-lg">edit_document</span>
                        Generate Defense Query
                      </button>
                    </div>
                  </div>
                ) : selectedClauseId === 'clause-4.4' ? (
                  <div className="space-y-4 fade-in">
                    <div className="p-4 bg-white border border-warning/50 rounded-sm shadow-sm">
                      <h4 className="text-warning font-bold flex items-center gap-2 mb-2 font-header text-lg">
                        <span className="material-symbols-outlined text-sm">warning</span>
                        Restrictive Turnover
                      </h4>
                      <p className="text-gray-600 text-sm leading-relaxed border-t border-warning/20 pt-2">
                        $500M turnover requirement excludes local MSMEs. Can be contested under <strong>Order 2017 (Make in India)</strong> which promotes local supplier participation.
                      </p>
                    </div>
                    <button 
                      className="w-full bg-primary hover:bg-navy-800 text-white py-3 rounded-sm font-bold text-sm uppercase tracking-wide flex items-center justify-center gap-2 transition-all shadow-md"
                      onClick={() => onViewChange(View.PREBID)}
                    >
                      <span className="material-symbols-outlined text-lg">edit_document</span>
                      Draft Query
                    </button>
                  </div>
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-accent fade-in pt-8">
                     <div className="w-16 h-16 rounded-full bg-accent/10 flex items-center justify-center mb-4 border border-accent/20">
                        <span className="material-symbols-outlined text-4xl">check_circle</span>
                     </div>
                     <p className="font-bold text-lg font-header">Clause Compliant</p>
                     <p className="text-xs text-gray-500 mt-2 text-center max-w-xs">No significant vigilance risks detected against standard procurement guidelines.</p>
                  </div>
                )
              )}
            </div>
          </div>

           {/* Terminal Output */}
           <div className="glass-panel rounded-lg overflow-hidden flex flex-col h-48 font-mono text-[10px] bg-gray-900 text-gray-200 border border-gray-300">
                <div className="bg-gray-800 px-3 py-1.5 text-gray-400 border-b border-gray-700 flex justify-between items-center">
                    <span className="flex items-center gap-2 font-bold"><span className="material-symbols-outlined text-[12px]">terminal</span> SYSTEM LOGS</span>
                    <span className="text-accent flex items-center gap-1 font-bold"><span className="w-1.5 h-1.5 rounded-full bg-accent"></span> ONLINE</span>
                </div>
                <div className="p-3 text-gray-300 overflow-y-auto flex-1 space-y-1 scroll-smooth">
                    {logs.length === 0 && <span className="text-gray-500 italic">>> Waiting for input...</span>}
                    {logs.map((log, i) => (
                        <div key={i} className="border-l-2 border-gray-700 hover:border-primary pl-2 py-0.5">{log}</div>
                    ))}
                    <div ref={logsEndRef}></div>
                </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default Analyzer;

