                <p className="text-[10px] text-gray-400 font-mono uppercase">Digitally Signed By</p>
                <p className="text-sm font-serif italic text-primary">{auditorSignature}</p>
            </div>
          )}

          <div className="mt-4 pt-4 flex gap-3 border-t border-gray-200">
            <button 
                onClick={handleRegenerate}
                className="flex-1 bg-white hover:bg-gray-50 text-gray-700 py-2 rounded text-sm border border-gray-300 transition-colors font-medium shadow-sm"
            >
              Regenerate
            </button>
            {legalStatus === 'pending' ? (
                <button 
                    onClick={requestLegalApproval}
                    className="flex-[2] bg-primary hover:bg-navy-800 text-white border border-transparent py-2 rounded text-sm font-bold flex items-center justify-center gap-2 transition-colors shadow-md"
                >
                    <span className="material-symbols-outlined text-sm">gavel</span>
                    Request Legal Approval
