            ) : (
                <button className="flex-[2] bg-accent hover:bg-teal-600 text-white py-2 rounded text-sm font-bold shadow-lg flex items-center justify-center gap-2 transition-colors">
                    <span className="material-symbols-outlined text-sm">send</span>
                    Add to Final Pack
                </button>
            )}
          </div>
        </div>
      </div>

      <LegalGateModal 
        isOpen={isLegalGateOpen} 
        onClose={() => setIsLegalGateOpen(false)}
        onApprove={handleLegalApprove}
      />
    </div>
  );
};

