      category: 'Services',
      state: 'Uttar Pradesh',
      isVerified: false,
      location: { lat: 26.8467, lng: 80.9462 }
    }
  ];

  // Filter Logic
  const filteredTenders = tenders.filter(t => {
    const matchesSearch = t.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.ref.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          t.tag.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === 'All' || t.category === filterCategory;
    const matchesState = filterState === 'All' || t.state === filterState;
    const matchesVerified = showUnverified ? true : t.isVerified;

    return matchesSearch && matchesCategory && matchesState && matchesVerified;
  });

  useEffect(() => {
    // Check if Leaflet is loaded
    const L = (window as any).L;
    if (!L || !mapContainerRef.current) return;

    // Initialize map if not already done
    if (!mapInstanceRef.current) {
      // Center on India
      const map = L.map(mapContainerRef.current, {
        zoomControl: false,
        attributionControl: true
      }).setView([22.5937, 78.9629], 5);

      mapInstanceRef.current = map;

      // Layer 1: Google Maps Hybrid (Satellite + Roads)
      L.tileLayer('https://mt1.google.com/vt/lyrs=y&x={x}&y={y}&z={z}', {
        attribution: 'Google Maps',
        maxZoom: 20
      }).addTo(map);

      // Add Zoom Control at bottom right
      L.control.zoom({
        position: 'bottomright'
      }).addTo(map);
    }

    // Update Markers whenever filteredTenders changes
    const map = mapInstanceRef.current;

    // Clear existing markers
    map.eachLayer((layer: any) => {
        if (layer instanceof L.Marker) {
            map.removeLayer(layer);
        }
    });

    const createIcon = (color: string, isVerified: boolean) => {
        const opacity = isVerified ? '1' : '0.5';
        const border = isVerified ? '2px solid #fff' : '2px dashed #eab308'; // Solid white vs Dashed Yellow
        return L.divIcon({
          className: 'custom-div-icon',
          html: `<div style="background-color: ${color}; width: 12px; height: 12px; border-radius: 50%; border: ${border}; opacity: ${opacity}; box-shadow: 0 0 5px rgba(0,0,0,0.5);"></div>`,
          iconSize: [12, 12],
          iconAnchor: [6, 6],
          popupAnchor: [0, -10]
        });
    };

    filteredTenders.forEach(t => {
        let color = '#0FB7B3'; // Default Teal
        if (t.risk) color = '#EF4444';
        else if (t.category === 'Services') color = '#A855F7';
        else if (!t.isVerified) color = '#64748B'; // Slate for unverified

        const marker = L.marker([t.location.lat, t.location.lng], { 
            icon: createIcon(color, t.isVerified) 
        }).addTo(map);

        const popupContent = `
          <div class="text-xs min-w-[200px]">
            <div class="flex justify-between items-center mb-1">
                <span class="font-bold text-white">${t.state}</span>
                ${!t.isVerified ? '<span class="text-[10px] text-yellow-500 font-bold border border-yellow-500/50 px-1 rounded">UNVERIFIED</span>' : ''}
            </div>
            <p class="text-slate-300 font-medium mb-1 line-clamp-2">${t.title}</p>
            <div class="flex justify-between text-[10px] text-slate-400 mt-2 border-t border-slate-700 pt-1">
                <span>Value: ${t.value}</span>
                <span>Due: ${t.due}</span>
            </div>
            <button onclick="window.navigateToView('analyzer')" class="mt-2 w-full bg-slate-700 hover:bg-slate-600 text-teal-400 py-1 rounded text-center font-bold">
              Analyze
            </button>
          </div>
        `;

        marker.bindPopup(popupContent);
    });

  }, [filteredTenders, showUnverified]);

  return (
    <div className="space-y-4 fade-in h-full flex flex-col text-slate-200">
      {/* Metrics Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 flex-none">
        <div className="glass-panel p-4 rounded border-l-4 border-teal-500 relative overflow-hidden group">
          <p className="text-slate-400 text-xs uppercase tracking-widest mb-1 font-semibold">Active Bids</p>
          <h2 className="text-3xl font-mono font-bold text-white">12</h2>
          <div className="mt-2 flex items-center gap-1 text-xs text-green-400 font-medium">
            <span className="material-symbols-outlined text-sm">trending_up</span>
            <span>+2 this week</span>
          </div>
        </div>

        <div className="glass-panel p-4 rounded border-l-4 border-gov-warning relative overflow-hidden group">
          <p className="text-slate-400 text-xs uppercase tracking-widest mb-1 font-semibold">Critical Alerts</p>
          <h2 className="text-3xl font-mono font-bold text-white">03</h2>
          <p className="text-xs text-slate-500 mt-2 font-medium">Requires immediate attention</p>
        </div>

        <div className="glass-panel p-4 rounded border-l-4 border-purple-500 relative overflow-hidden group">
          <p className="text-slate-400 text-xs uppercase tracking-widest mb-1 font-semibold">Avg. P-Win</p>
          <h2 className="text-3xl font-mono font-bold text-white">68%</h2>
          <div className="w-full bg-slate-700 h-1 mt-3 rounded-full overflow-hidden">
            <div className="bg-purple-500 h-full" style={{ width: '68%' }}></div>
          </div>
        </div>

        <div className="glass-panel p-4 rounded border-l-4 border-green-500 relative overflow-hidden group">
          <p className="text-slate-400 text-xs uppercase tracking-widest mb-1 font-semibold">Compliance</p>
          <h2 className="text-3xl font-mono font-bold text-white">98%</h2>
          <p className="text-xs text-slate-500 mt-2 font-medium">Audit Trail Validated</p>
        </div>
      </div>

      {/* Command Bar: Filters & Adapters */}
      <div className="glass-panel p-3 rounded flex flex-wrap items-center gap-4 border-slate-700 bg-slate-900/50">
          <div className="flex items-center gap-2 pr-4 border-r border-slate-700">
             <span className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Ingest Adapters</span>
             <div className="flex gap-1">
                 <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" title="GeM API: Connected"></div>
                 <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse delay-75" title="CPPP XML: Connected"></div>
                 <div className="w-2 h-2 rounded-full bg-slate-600" title="Manual: Idle"></div>
             </div>
          </div>

          {/* Filter Controls */}
          <div className="flex items-center gap-3 flex-1 overflow-x-auto">
             <select 
                value={filterCategory} 
                onChange={e => setFilterCategory(e.target.value)}
                className="bg-slate-950 border border-slate-700 rounded px-2 py-1 text-xs text-white focus:border-teal-500 outline-none"
             >
                 <option value="All">All Categories</option>
                 <option value="Goods">Goods</option>
                 <option value="Services">Services</option>
                 <option value="Works">Works</option>
             </select>

             <select 
                value={filterState} 
                onChange={e => setFilterState(e.target.value)}
                className="bg-slate-950 border border-slate-700 rounded px-2 py-1 text-xs text-white focus:border-teal-500 outline-none"
             >
                 <option value="All">All States</option>
                 <option value="Maharashtra">Maharashtra</option>
                 <option value="Delhi">Delhi</option>
                 <option value="Karnataka">Karnataka</option>
                 <option value="Uttar Pradesh">Uttar Pradesh</option>
             </select>

             <label className="flex items-center gap-2 cursor-pointer bg-slate-950 px-2 py-1 rounded border border-slate-700">
                 <input 
                    type="checkbox" 
                    checked={showUnverified} 
                    onChange={e => setShowUnverified(e.target.checked)}
                    className="accent-teal-500"
                 />
                 <span className="text-xs text-slate-300">Show Unverified</span>
             </label>
          </div>
      </div>

      {/* Main Dashboard Content */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 flex-1 min-h-[400px]">
        {/* Map Section */}
        <div className="lg:col-span-2 glass-panel rounded overflow-hidden flex flex-col h-full min-h-[400px]">
          <div className="p-4 border-b border-slate-700 flex justify-between items-center bg-navy-900">
            <h3 className="font-semibold text-white flex items-center gap-2">
              <span className="material-symbols-outlined text-teal-400">public</span>
              Verified Tenders (ap-south-1)
            </h3>
            <div className="flex gap-2">
              <button 
                className="px-3 py-1 bg-slate-800 text-xs rounded hover:bg-slate-700 text-slate-300 border border-slate-700"
                onClick={() => {
                   if(mapInstanceRef.current) mapInstanceRef.current.flyTo([22.5937, 78.9629], 5);
                }}
              >
                Reset View
              </button>
            </div>
          </div>

          <div className="flex-1 w-full relative bg-slate-900">
             <div ref={mapContainerRef} className="absolute inset-0 z-0"></div>
          </div>
        </div>

        {/* Tender Feed */}
        <div className="glass-panel rounded overflow-hidden flex flex-col h-full max-h-[calc(100vh-250px)]">
          <div className="p-4 border-b border-slate-700 bg-navy-900 space-y-3 shrink-0">
            <h3 className="font-semibold text-white">Priority Feed</h3>

            {/* Search Bar */}
            <div className="relative">
              <input 
                type="text" 
                placeholder="Search ID, Title..." 
                className="w-full bg-slate-950 border border-slate-700 rounded py-2 pl-9 pr-4 text-xs text-white focus:outline-none focus:border-teal-500 transition-colors placeholder:text-slate-600"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <span className="material-symbols-outlined absolute left-2.5 top-2 text-slate-500 text-sm">search</span>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {filteredTenders.length === 0 ? (
              <div className="text-center text-slate-500 py-8 text-xs">
                No tenders found matching criteria.
              </div>
            ) : (
              filteredTenders.map(tender => (
                <div 
                  key={tender.id}
                  className={`p-3 bg-slate-800 rounded border transition-colors cursor-pointer group relative ${tender.isVerified ? 'border-slate-700 hover:border-teal-500' : 'border-slate-700 border-dashed hover:border-yellow-500'}`}
                  onClick={() => onViewChange(View.ANALYZER)}
                >
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-xs font-mono text-teal-500 font-semibold">{tender.ref}</span>
                    <span className={`text-[10px] px-1.5 py-0.5 rounded border font-semibold ${tender.tagColor}`}>
                      {tender.tag}
                    </span>
                  </div>
                  <h4 className="text-sm font-bold text-slate-200 group-hover:text-teal-400">{tender.title}</h4>
                  <p className="text-xs text-slate-400 mt-1 font-medium">Due: {tender.due} • Value: {tender.value}</p>

                  {!tender.isVerified && (
                      <div className="absolute top-2 right-2 opacity-10 text-yellow-500">
                          <span className="material-symbols-outlined text-4xl">warning</span>
                      </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef, useEffect } from 'react';
import { View } from '../types';

interface AnalyzerProps {
  onViewChange: (view: View) => void;
}

const Analyzer: React.FC<AnalyzerProps> = ({ onViewChange }) => {
  const [file, setFile] = useState<File | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [scanProgress, setScanProgress] = useState(0);
  const [scanComplete, setScanComplete] = useState(false);
  const [selectedClauseId, setSelectedClauseId] = useState<string | null>(null);
  const [logs, setLogs] = useState<string[]>([]);
  const [riskScore, setRiskScore] = useState(0);
  const logsEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Risk Keywords (Professional Set)
  const riskKeywords = ['violation', 'non-compliance', 'restrictive', 'monopoly', 'unclear', 'foreign', 'mandatory', 'exclude', 'proprietory', 'turnover'];

  // Mock PDF Text content
  const pdfSections = [
    {
      id: 'clause-4.1',
      title: '4.1 Video Management System (VMS)',
      text: 'The VMS shall support ONVIF Profile S and G. It must be capable of handling 5000+ cameras concurrently.'
    },
    {
      id: 'clause-4.2',
      title: '4.2 Hosting Requirements (CRITICAL FLAG)',
      text: 'The proposed cloud solution must have a primary data center located in the United States or Europe. This is a restrictive condition creating a monopoly for foreign providers and implies non-compliance with data localization norms.',
      risky: true
    },
    {
      id: 'clause-4.3',
      title: '4.3 Analytics',
      text: 'The system must support facial recognition with 99% accuracy.'
    },
    {
      id: 'clause-4.4',
      title: '4.4 Hardware OEM',
      text: 'The OEM for cameras must have been operating in India for at least 10 years and have a turnover of $500M. This mandatory requirement is unclear and may exclude local MSMEs.'
    }
  ];

  // Auto-scroll logs
  useEffect(() => {
    if (logsEndRef.current) {
      logsEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [logs]);

  const addLog = (message: string) => {
    const timestamp = new Date().toISOString().split('T')[1].slice(0, 8);
    setLogs(prev => [...prev, `[${timestamp}] ${message}`]);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const selectedFile = e.target.files[0];
      if (selectedFile.type !== 'application/pdf') {
        alert("System Protocol Error: Only PDF documents are accepted for parsing.");
        return;
      }
      setFile(selectedFile);
      setScanComplete(false);
      setRiskScore(0);
      setLogs([]);
      addLog(`Secure File Mount: ${selectedFile.name}`);
      addLog(`Size: ${(selectedFile.size / 1024).toFixed(2)} KB | Type: application/pdf`);
      addLog("Ready for deep inspection.");
    }
  };

  const highlightText = (text: string) => {
    if (!selectedClauseId) return text; 

    const parts = text.split(new RegExp(`(${riskKeywords.join('|')})`, 'gi'));
    return (
      <span>
        {parts.map((part, i) => 
          riskKeywords.some(k => k.toLowerCase() === part.toLowerCase()) ? (
            <span key={i} className="bg-red-500/20 text-red-400 px-1 rounded border-b border-red-500 font-semibold" title="Risk Pattern Detected">
              {part}
            </span>
          ) : (
            part
          )
        )}
      </span>
    );
  };

  const triggerScan = () => {
    if (!file) return;

    setIsScanning(true);
    setScanProgress(0);
    setLogs([]);
    setSelectedClauseId(null);
    setRiskScore(0);

    let progress = 0;
    const interval = setInterval(() => {
        progress += Math.floor(Math.random() * 5) + 1;
        if (progress > 100) progress = 100;
        setScanProgress(progress);
    }, 150);

    setTimeout(() => addLog(`Initializing Sentinel OCR Engine v2.4...`), 100);
    setTimeout(() => addLog("Establishing secure enclave connection (AES-256)..."), 800);
    setTimeout(() => addLog("Extracting text layer and embedded metadata..."), 1500);
    setTimeout(() => {
      let foundRisks = 0;
      pdfSections.forEach(section => {
        riskKeywords.forEach(kw => {
           if (section.text.toLowerCase().includes(kw)) foundRisks++;
        });
      });
      setRiskScore(foundRisks * 15);
      addLog(`Semantic Analysis completed. Identified ${foundRisks} potential risk vectors.`);
    }, 4000);

    setTimeout(() => {
      clearInterval(interval);
      setScanProgress(100);
      setIsScanning(false);
      setScanComplete(true);
      addLog("Report generated successfully.");
      setSelectedClauseId('clause-4.2'); 
    }, 5500);
  };

  const handleClauseClick = (id: string) => {
    setSelectedClauseId(id);
  };

  return (
    <div className="space-y-6 h-full flex flex-col fade-in text-slate-200">
      {/* Top Header */}
      <div className="flex justify-between items-center bg-navy-900/50 border-b border-slate-700 pb-4">
        <div>
            <h2 className="text-2xl font-bold text-white font-header tracking-wide flex items-center gap-2">
              <span className="material-symbols-outlined text-teal-400">analytics</span>
              RFP ANALYZER
            </h2>
            <p className="text-xs text-slate-500 font-mono mt-1">SENTINEL INTELLIGENCE CORE // V2.0</p>
        </div>
        <div className="flex items-center gap-6">
             {riskScore > 0 && (
                 <div className="flex items-center gap-3 px-4 py-2 rounded border border-red-500/30 bg-red-500/10">
                    <span className="material-symbols-outlined text-red-500">warning</span>
                    <div className="text-right">
                      <p className="text-[10px] text-red-400 font-bold uppercase tracking-wider">Risk Index</p>
                      <p className="text-xl font-bold text-white leading-none font-header">{riskScore}/100</p>
                    </div>
                 </div>
             )}
        </div>
      </div>

      {/* Main Workspace */}
      <div className="grid grid-cols-12 gap-6 flex-1 min-h-0">

        {/* Left: Document Processing Unit */}
        <div className={`col-span-12 lg:col-span-7 glass-panel rounded-lg overflow-hidden flex flex-col relative scanner-container ${isScanning ? 'scanning' : ''}`}>

          {/* File Upload / Status Header */}
          <div className="bg-slate-900 p-4 border-b border-slate-700 flex justify-between items-center">
            {file ? (
              <div className="flex items-center gap-3 bg-slate-800 px-3 py-1.5 rounded border border-slate-700">
                <span className="material-symbols-outlined text-red-400">picture_as_pdf</span>
                <div>
                   <p className="text-sm font-medium text-slate-200">{file.name}</p>
                   <p className="text-[10px] text-slate-500 uppercase tracking-wide">{(file.size / 1024 / 1024).toFixed(2)} MB • VERIFIED</p>
                </div>
                <button onClick={() => setFile(null)} className="ml-2 text-slate-500 hover:text-red-400">
                    <span className="material-symbols-outlined text-sm">close</span>
                </button>
              </div>
            ) : (
               <div className="flex items-center gap-2 text-slate-500 text-sm">
                   <span className="material-symbols-outlined">folder_off</span>
                   <span>No active document context</span>
               </div>
            )}

            <div className="flex gap-3">
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                accept="application/pdf" 
                className="hidden" 
              />
              {!file && (
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="bg-slate-800 hover:bg-slate-700 text-slate-300 px-4 py-2 rounded-sm text-xs font-medium border border-slate-600 transition-colors flex items-center gap-2 shadow-sm"
                >
                  <span className="material-symbols-outlined text-sm">upload_file</span>
                  UPLOAD RFP
                </button>
              )}

              <button 
                className={`px-5 py-2 rounded-sm text-xs font-bold uppercase tracking-wider transition-all flex items-center gap-2 ${
                  !file || isScanning 
                    ? 'bg-slate-800 text-slate-600 cursor-not-allowed border border-slate-700' 
                    : 'bg-teal-600 hover:bg-teal-500 text-white shadow-md shadow-teal-900/20 border border-teal-500'
                }`}
                onClick={triggerScan}
                disabled={!file || isScanning}
              >
                {isScanning ? (
                  <>SCANNING {(scanProgress).toFixed(0)}%</>
                ) : (
                  <>INITIATE SCAN</>
                )}
              </button>
            </div>
          </div>

          <div className="scanner-line"></div>

          {/* Document Viewer Area */}
          <div className="flex-1 bg-slate-100 text-slate-900 font-serif text-sm overflow-y-auto relative selection:bg-teal-200 p-8 shadow-inner">
            {!file ? (
              <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-70">
                 <div className="w-20 h-20 border-2 border-dashed border-slate-300 rounded-lg flex items-center justify-center mb-4">
                    <span className="material-symbols-outlined text-4xl">cloud_upload</span>
                 </div>
                 <p className="text-lg font-sans font-semibold text-slate-500">Upload Tender Document</p>
                 <p className="text-xs mt-1 font-mono">SECURE UPLOAD // PDF FORMAT ONLY</p>
              </div>
            ) : !scanComplete && !isScanning ? (
               <div className="h-full flex flex-col items-center justify-center fade-in">
                  <div className="w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mb-4 border border-blue-100">
                    <span className="material-symbols-outlined text-3xl text-blue-500">visibility</span>
                  </div>
                  <p className="text-slate-700 font-sans font-bold text-lg">Document Preview Locked</p>
                  <p className="text-xs text-slate-500 mt-2 font-mono bg-white px-2 py-1 rounded border border-slate-200">
                      WAITING FOR NEURAL ANALYSIS
                  </p>
               </div>
            ) : (
              // Content Rendering
              <div className="max-w-3xl mx-auto space-y-6 animate-in fade-in duration-500">
                <div className="flex justify-between items-end border-b-2 border-slate-300 pb-4 mb-8">
                  <div>
                    <h1 className="text-xl font-bold uppercase tracking-wide font-header text-slate-900">Request For Proposal</h1>
                    <p className="text-xs text-slate-500 mt-1 font-mono">REF: {file.name.toUpperCase().replace('.PDF', '')}</p>
                  </div>
                  <div className="text-right">
                      <p className="text-[10px] uppercase font-bold text-slate-400">Classification</p>
                      <p className="text-sm font-bold text-slate-900">PUBLIC / OPEN TENDER</p>
                  </div>
                </div>

                <p className="font-bold text-lg border-b pb-2 border-slate-300 text-slate-800 font-header">SECTION IV: TECHNICAL SPECIFICATIONS</p>

                {pdfSections.map((section) => (
                  <div 
                      key={section.id}
                      className={`p-4 rounded-sm transition-all duration-200 border-l-4 ${
                          selectedClauseId === section.id 
                              ? section.id.includes('4.2') || section.id.includes('4.4') 
                                  ? 'border-l-red-500 bg-red-50 ring-1 ring-red-100 shadow-sm'
                                  : 'border-l-teal-500 bg-teal-50 ring-1 ring-teal-100 shadow-sm' 
                              : 'border-l-transparent hover:bg-slate-200'
                      } ${section.risky && !selectedClauseId ? 'bg-red-50/50' : ''} cursor-pointer group`}
                      onClick={() => handleClauseClick(section.id)}
                  >
                      <div className="flex justify-between mb-1">
                          <span className="font-bold block text-slate-800 group-hover:text-teal-700">{section.title}</span>
                          {section.risky && <span className="text-[10px] font-bold bg-red-100 text-red-600 px-1.5 py-0.5 rounded border border-red-200">RISK DETECTED</span>}
                      </div>
                      <span className="leading-relaxed text-slate-700">
                          {highlightText(section.text)}
                      </span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Right: Intelligence Panel */}
        <div className="col-span-12 lg:col-span-5 flex flex-col gap-4">

          {/* Analysis Results */}
          <div className="glass-panel p-0 rounded-lg flex-1 flex flex-col min-h-[300px] overflow-hidden border-slate-700">
            <div className="p-3 border-b border-slate-700 bg-slate-900 flex justify-between items-center">
               <h3 className="font-semibold text-white font-header flex items-center gap-2">
                 <span className="material-symbols-outlined text-teal-400 text-lg">psychology</span>
                 TACTICAL INSIGHTS
               </h3>
               {selectedClauseId && (
                   <button onClick={() => setSelectedClauseId(null)} className="text-[10px] text-slate-400 hover:text-white uppercase font-bold">Clear Selection</button>
