            }

        # 2. Fuzzy Match Fallback
        ratio = fuzz.partial_ratio(claimed_snippet, doc['text'])
        if ratio >= 92:
            return {
                "status": "FUZZY_FLAGGED", 
                "reason": "Requires Human Review",
                "score": ratio
            }

        return {"status": "BLOCKED", "reason": "NO_MATCH_FOUND", "score": ratio}
```

