// IngestTenderHandler handles Manual Uploads (Multipart Form)
func IngestTenderHandler(c *fiber.Ctx) error {
	// 1. Parse Metadata
	title := c.FormValue("title")
	refID := c.FormValue("ref_id")
	category := c.FormValue("category")
	valueStr := c.FormValue("value")

	value, _ := strconv.ParseFloat(valueStr, 64)

	// 2. Handle File
	file, err := c.FormFile("pdf_file")
	if err != nil {
		return c.Status(400).JSON(fiber.Map{"error": "PDF File is mandatory"})
	}

	// 3. Mock Save to Storage (S3)
	// s3.Upload(file)
	s3Key := "tenders/manual/" + file.Filename

	// 4. Create Record
	metadata := adapters.TenderMetadata{
		SourceRefID:  refID,
		Title:        title,
		Category:     category,
		ValueINR:     value,
		PublishDate:  time.Now(),
		ClosingDate:  time.Now().AddDate(0, 0, 30), // Default
		Location:     "Manual Upload",
		Organization: "Unknown",
		IsVerified:   false, // Manual uploads are unverified by default
		SourceSystem: "MANUAL",
		DownloadURL:  s3Key,
	}

	log.Printf("[AUDIT] MANUAL_INGEST: User=%s Ref=%s File=%s", "unknown", refID, file.Filename)

	return c.JSON(fiber.Map{
		"status": "INGESTED",
		"id":     uuid.New().String(),
		"data":   metadata,
		"message": "Tender uploaded successfully. Status: UNVERIFIED (Pending Operator Review).",
	})
}

// SyncTendersHandler triggers the GeM/CPPP adapters
func SyncTendersHandler(c *fiber.Ctx) error {
	source := c.Query("source", "GEM")

	var adapter adapters.TenderSource

	switch source {
	case "GEM":
		adapter = adapters.NewGeMAdapter("mock-key")
	default:
		return c.Status(400).JSON(fiber.Map{"error": "Unsupported source"})
	}

	tenders, err := adapter.FetchTenders()
	if err != nil {
		return c.Status(500).JSON(fiber.Map{"error": "Adapter fetch failed"})
	}

	// Mock DB Insertion loop
	// for t := range tenders { db.Save(t) }

	log.Printf("[AUDIT] ADAPTER_SYNC: Source=%s Count=%d", source, len(tenders))

	return c.JSON(fiber.Map{
		"status": "SYNC_COMPLETE",
		"source": source,
		"new_tenders": len(tenders),
		"data": tenders,
	})
}

// CommercialWebhookHandler receives feed updates (Stub)
func CommercialWebhookHandler(c *fiber.Ctx) error {
	var payload map[string]interface{}
	if err := c.BodyParser(&payload); err != nil {
		return c.Status(400).JSON(fiber.Map{"error": "Invalid Payload"})
	}

	log.Printf("[AUDIT] WEBHOOK_RECEIVED: %v", payload)

	return c.JSON(fiber.Map{"status": "RECEIVED"})
}

package main

import (
	"log"

	"github.com/gofiber/fiber/v2"
	"github.com/gofiber/fiber/v2/middleware/cors"
	"github.com/gofiber/fiber/v2/middleware/helmet"
	"github.com/gofiber/fiber/v2/middleware/logger"

	"github.com/gov-india/sentinel-bharat/backend/api"
	"github.com/gov-india/sentinel-bharat/backend/auth"
	"github.com/gov-india/sentinel-bharat/backend/config"
)

func main() {
	// 1. Config & Safety Checks
	cfg := config.Load()
	if cfg.Region != "ap-south-1" {
		log.Printf("WARNING: Data Residency Check Failed. Expected ap-south-1, got %s", cfg.Region)
	}

	// 2. Fiber App
	app := fiber.New(fiber.Config{
		AppName:       "Sentinel Prime Core v1.2",
		ServerHeader:  "Sentinel-Secure",
		CaseSensitive: true,
		StrictRouting: true,
		BodyLimit:     100 * 1024 * 1024,
	})

	// 3. Middleware
	app.Use(logger.New())
	app.Use(helmet.New())
	app.Use(cors.New(cors.Config{
		AllowOrigins: "https://sentinel.gov.in, http://localhost:3000",
		AllowHeaders: "Origin, Content-Type, Accept, Authorization, X-Sentinel-2FA",
		AllowMethods: "GET, POST, PUT, DELETE, OPTIONS",
	}))

	// 4. Routes
	apiGroup := app.Group("/api/v1")
	authHandler := auth.NewHandler()

	// Auth Routes
	authGroup := apiGroup.Group("/auth")
	authGroup.Post("/login", authHandler.Login)
	authGroup.Post("/refresh", authHandler.Refresh)
	authGroup.Post("/forgot-password", authHandler.RequestPasswordReset)

	// Admin Only Auth Management
	authGroup.Post("/admin/approve-reset", auth.RequireRole("Admin"), authHandler.AdminApproveReset)

	// Onboarding Routes
	onboarding := apiGroup.Group("/onboarding")
	onboarding.Post("/register", api.RegisterVendorHandler)

	// Protected Routes (JWT Required)
	protected := apiGroup.Use(auth.JwtMiddleware)

	// Ingestion Routes
	protected.Post("/tenders/ingest", api.IngestTenderHandler)
	protected.Post("/tenders/sync", api.SyncTendersHandler)
	protected.Post("/webhooks/feed", api.CommercialWebhookHandler)

	protected.Get("/analysis/clauses/:id", api.GetClausesHandler)
	protected.Post("/verify/citation", api.VerifyCitationHandler)

	// Vault
	vault := protected.Group("/vault")
	vault.Get("/keys", api.GetVaultKeysHandler)
	vault.Post("/wallet/connect", api.ConnectWalletHandler)
	vault.Post("/upload", api.UploadVaultFileHandler)
	vault.Post("/map", api.MapEvidenceHandler)
	vault.Post("/verify", api.VerifyEvidenceHandler)
	vault.Post("/manifest/generate", api.GenerateManifestHandler)
	vault.Post("/sign-manifest", api.SignManifestHandler) 

	// Legal
	legal := protected.Use(auth.RequireRole("Legal-Auditor", "Admin"))
	legal.Post("/legal/approve", auth.Require2FA, api.ApproveDraftHandler)
	legal.Get("/legal/queue", func(c *fiber.Ctx) error {
		return c.JSON(fiber.Map{"queue": "mock_queue"})
	})

	// 5. Start
	log.Printf("Sentinel Prime Core active on :%s (Region: %s)", cfg.Port, cfg.Region)
	log.Fatal(app.Listen(":" + cfg.Port))
}

