package services

import (
	"fmt"
	"strings"
)

// GenerateQuery constructs a pre-bid query based on the strategy and risk profile
func GenerateQuery(clauseID, clauseText, category, tone string, citations []string) string {

	// Base Template Selection
	var template string
	switch tone {
	case "neutral":
		template = "Ref Clause %s (%s):\n\nRequest for clarification: %s\n\nWe request the authority to clarify if this condition is mandatory or if equivalent standards are accepted."
	case "strict":
		template = "Ref Clause %s (%s) - NOTICE OF RESTRICTIVE CONDITION:\n\nThe current clause mandates \"%s\".\n\nThis requirement explicitly excludes competent domestic bidders and violates CVC guidelines on fair competition. \n\nLegal Reference: %s\n\nRequest: The clause MUST be rectified immediately."
	case "advisory":
		fallthrough
	default:
		template = "Ref Clause %s (%s):\n\nObservation: The clause stipulates \"%s\".\n\nSubmission: We respectfully submit that this condition appears to be in contradiction with %s.\n\nRequest: Please amend the clause to ensure compliance with GOI statutory requirements and allow broader participation."
	}

	// Extract a snippet from the clause for context (first 10 words or meaningful chunk)
	snippet := clauseText
	if len(snippet) > 50 {
		snippet = snippet[:50] + "..."
	}

	// Format Citations
	citationText := "relevant government guidelines"
	if len(citations) > 0 {
		citationText = strings.Join(citations, " and ")
	}

	// Construct Query
	query := fmt.Sprintf(template, clauseID, category, snippet, citationText)
	return query
}

package api

import (
	"log"
	"time"

	"github.com/gofiber/fiber/v2"
	"github.com/google/uuid"
	"github.com/gov-india/sentinel-bharat/backend/services"
)

// Ticket represents a Pre-Bid Draft awaiting Legal Approval
type Ticket struct {
	ID                string    `json:"id"`
	TenderID          string    `json:"tender_id"`
	ClauseID          string    `json:"clause_id"`
	Title             string    `json:"title"`
	QueryText         string    `json:"query_text"`
	Author            string    `json:"author"`
	RiskLevel         string    `json:"risk"`
	Status            string    `json:"status"` // PENDING, APPROVED, REJECTED
	Citations         []string  `json:"citations"`
	CreatedAt         time.Time `json:"created_at"`
	ApprovalSignature string    `json:"approval_signature,omitempty"`
	ApproverID        string    `json:"approver_id,omitempty"`
}

// In-memory store for pilot
var TicketStore = []Ticket{}

type CreateDraftRequest struct {
	TenderID   string   `json:"tender_id"`
	ClauseID   string   `json:"clause_id"`
	ClauseText string   `json:"clause_text"`
	Category   string   `json:"category"`
	Tone       string   `json:"tone"`
	Risk       string   `json:"risk"`
	Citations  []string `json:"citations"`
}

// CreateDraftHandler generates a query and creates a ticket
func CreateDraftHandler(c *fiber.Ctx) error {
	var req CreateDraftRequest
	if err := c.BodyParser(&req); err != nil {
		return c.Status(400).JSON(fiber.Map{"error": "Invalid payload"})
	}

	// 1. Generate Query Text via Service
	generatedText := services.GenerateQuery(
		req.ClauseID, 
		req.ClauseText, 
		req.Category, 
		req.Tone, 
		req.Citations,
	)

	// 2. Create Ticket
	ticket := Ticket{
		ID:        "TKT-" + uuid.New().String()[:8],
		TenderID:  req.TenderID,
		ClauseID:  req.ClauseID,
		Title:     "Query: " + req.Category,
		QueryText: generatedText,
		Author:    "Vendor User", // In prod, get from JWT
		RiskLevel: req.Risk,
		Status:    "PENDING",
		Citations: req.Citations,
		CreatedAt: time.Now(),
	}

	TicketStore = append(TicketStore, ticket)

	log.Printf("[AUDIT] DRAFT_CREATED: ID=%s Tender=%s Risk=%s", ticket.ID, ticket.TenderID, ticket.RiskLevel)

	return c.JSON(fiber.Map{
		"status": "CREATED",
		"ticket": ticket,
		"message": "Draft generated and submitted to Legal Queue.",
	})
}

package api

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"log"
	"time"

	"github.com/gofiber/fiber/v2"
)

type ApprovalRequest struct {
	TicketID  string `json:"ticket_id"`
	Decision  string `json:"decision"` // APPROVED | REJECTED
	Signature string `json:"signature"` // Name of auditor
	TOTPCode  string `json:"totp_code"`
}

// GetLegalQueueHandler returns pending tickets
func GetLegalQueueHandler(c *fiber.Ctx) error {
	// Filter for PENDING tickets
	var pending []Ticket
	for _, t := range TicketStore {
		if t.Status == "PENDING" {
			pending = append(pending, t)
		}
	}
	return c.JSON(fiber.Map{"queue": pending})
}

// ApproveTicketHandler handles the 2FA sign-off
func ApproveTicketHandler(c *fiber.Ctx) error {
	var req ApprovalRequest
	if err := c.BodyParser(&req); err != nil {
		return c.Status(400).JSON(fiber.Map{"error": "Invalid payload"})
	}

	// 1. Validate Ticket Existence
	var targetIdx int = -1
	for i, t := range TicketStore {
		if t.ID == req.TicketID {
			targetIdx = i
			break
		}
	}

	if targetIdx == -1 {
		return c.Status(404).JSON(fiber.Map{"error": "Ticket not found"})
	}

	// 2. Validate Decision
	if req.Decision != "APPROVED" && req.Decision != "REJECTED" {
		return c.Status(400).JSON(fiber.Map{"error": "Invalid decision"})
	}

	// 3. Cryptographic Sign-off (Mock 2FA validation passed by middleware)
	// Create an immutable hash of the approval
	payload := fmt.Sprintf("%s:%s:%s:%s", req.TicketID, req.Decision, req.Signature, time.Now().String())
	hash := sha256.Sum256([]byte(payload))
	signatureHash := hex.EncodeToString(hash[:])

	// 4. Update Ticket
	TicketStore[targetIdx].Status = req.Decision
	TicketStore[targetIdx].ApprovalSignature = signatureHash
	TicketStore[targetIdx].ApproverID = req.Signature // Using name as ID for pilot

	// 5. Audit Log
	log.Printf("[AUDIT] LEGAL_DECISION: Ticket=%s Decision=%s Signer=%s Sig=%s", 
		req.TicketID, req.Decision, req.Signature, signatureHash)

	return c.JSON(fiber.Map{
		"status": "SUCCESS",
		"ticket_id": req.TicketID,
		"new_status": req.Decision,
		"approval_hash": signatureHash,
	})
}

package main

import (
	"log"

	"github.com/gofiber/fiber/v2"
	"github.com/gofiber/fiber/v2/middleware/cors"
	"github.com/gofiber/fiber/v2/middleware/helmet"
	"github.com/gofiber/fiber/v2/middleware/logger"

	"github.com/gov-india/sentinel-bharat/backend/api"
	"github.com/gov-india/sentinel-bharat/backend/auth"
	"github.com/gov-india/sentinel-bharat/backend/config"
)

func main() {
	// 1. Config & Safety Checks
	cfg := config.Load()
	if cfg.Region != "ap-south-1" {
		log.Printf("WARNING: Data Residency Check Failed. Expected ap-south-1, got %s", cfg.Region)
	}

	// 2. Fiber App
	app := fiber.New(fiber.Config{
		AppName:       "Sentinel Prime Core v1.2",
		ServerHeader:  "Sentinel-Secure",
		CaseSensitive: true,
		StrictRouting: true,
		BodyLimit:     100 * 1024 * 1024,
	})

	// 3. Middleware
	app.Use(logger.New())
	app.Use(helmet.New())
	app.Use(cors.New(cors.Config{
		AllowOrigins: "https://sentinel.gov.in, http://localhost:3000",
		AllowHeaders: "Origin, Content-Type, Accept, Authorization, X-Sentinel-2FA",
		AllowMethods: "GET, POST, PUT, DELETE, OPTIONS",
	}))

	// 4. Routes
	apiGroup := app.Group("/api/v1")
	authHandler := auth.NewHandler()

	// Auth Routes
	authGroup := apiGroup.Group("/auth")
	authGroup.Post("/login", authHandler.Login)
	authGroup.Post("/refresh", authHandler.Refresh)
	authGroup.Post("/forgot-password", authHandler.RequestPasswordReset)
	authGroup.Post("/admin/approve-reset", auth.RequireRole("Admin"), authHandler.AdminApproveReset)

	// Onboarding Routes
	onboarding := apiGroup.Group("/onboarding")
	onboarding.Post("/register", api.RegisterVendorHandler)

	// Protected Routes (JWT Required)
	protected := apiGroup.Use(auth.JwtMiddleware)

	// Ingestion Routes
	protected.Post("/tenders/ingest", api.IngestTenderHandler)
	protected.Post("/tenders/sync", api.SyncTendersHandler)
	protected.Post("/webhooks/feed", api.CommercialWebhookHandler)

	protected.Get("/analysis/clauses/:id", api.GetClausesHandler)
	protected.Post("/verify/citation", api.VerifyCitationHandler)

	// Pre-Bid Routes
	protected.Post("/prebid/draft", api.CreateDraftHandler)

	// Vault
	vault := protected.Group("/vault")
	vault.Get("/keys", api.GetVaultKeysHandler)
	vault.Post("/wallet/connect", api.ConnectWalletHandler)
	vault.Post("/upload", api.UploadVaultFileHandler)
	vault.Post("/map", api.MapEvidenceHandler)
	vault.Post("/verify", api.VerifyEvidenceHandler)
	vault.Post("/manifest/generate", api.GenerateManifestHandler)
	vault.Post("/sign-manifest", api.SignManifestHandler) 

	// Legal Routes (RBAC Enforced)
	legal := protected.Use(auth.RequireRole("Legal-Auditor", "Admin"))
	legal.Get("/legal/queue", api.GetLegalQueueHandler)
	// Require 2FA middleware for approval
	legal.Post("/legal/approve", auth.Require2FA, api.ApproveTicketHandler)

	// 5. Start
	log.Printf("Sentinel Prime Core active on :%s (Region: %s)", cfg.Port, cfg.Region)
	log.Fatal(app.Listen(":" + cfg.Port))
}

import React, { useState, useEffect } from 'react';
import { View } from '../types';
import VerificationModal from './VerificationModal';

interface PreBidStudioProps {
  onViewChange: (view: View) => void;
  onOpenModal: () => void;
}

const PreBidStudio: React.FC<PreBidStudioProps> = ({ onViewChange, onOpenModal }) => {
  const [tone, setTone] = useState<'neutral' | 'advisory' | 'strict'>('advisory');
  const [isGenerating, setIsGenerating] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [queryText, setQueryText] = useState('');

  // Mock Context (In real app, this comes from the selected Clause in Analyzer)
  const context = {
    tenderId: "GEM/2025/B/4829",
    clauseId: "4.2",
    clauseText: "The proposed cloud solution must have a primary data center located in the United States or Europe.",
    category: "Data Residency",
    risk: "CRITICAL",
    citations: ["DPDP Act 2023", "MeitY Guidelines"]
  };

  const handleGenerate = async (selectedTone: 'neutral' | 'advisory' | 'strict') => {
    setIsGenerating(true);
    setTone(selectedTone);

    // Simulate generation latency
    setTimeout(() => {
        // This simulates the backend logic for immediate feedback, 
        // real text will be confirmed on submit.
        let text = "";
        if (selectedTone === 'neutral') {
           text = `Ref Clause ${context.clauseId} (${context.category}):\n\nRequest for clarification: Does the Department explicitly require hosting outside India?\nWe request the authority to allow MeitY Empanelled Cloud Service Providers (CSPs) within India to participate.`;
        } else if (selectedTone === 'advisory') {
           text = `Ref Clause ${context.clauseId} (${context.category}):\n\nThe current clause specifies foreign hosting. We respectfully submit that this appears to be in contradiction with the ${context.citations.join(" and ")} regarding sensitive government data.\n\nRequest: Please amend the clause to mandate "MeitY Empanelled Cloud Service Provider within India".`;
        } else {
           text = `Ref Clause ${context.clauseId} (${context.category}) - CRITICAL VIOLATION:\n\nThe requirement for foreign data residency strictly violates ${context.citations[0]} and CVC Circulars. Mandating foreign hosting creates a monopoly.\n\nRequest: The clause MUST be rectified immediately.`;
        }
        setQueryText(text);
        setIsGenerating(false);
    }, 600);
  };

  useEffect(() => {
    handleGenerate('advisory');
  }, []);

  const handleSubmit = async () => {
    setIsSubmitting(true);
    try {
        const token = localStorage.getItem('token') || 'mock-token'; // In prod, use Context
        const response = await fetch('http://localhost:8080/api/v1/prebid/draft', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`
            },
            body: JSON.stringify({
                tender_id: context.tenderId,
                clause_id: context.clauseId,
                clause_text: context.clauseText,
                category: context.category,
                tone: tone,
                risk: context.risk,
                citations: context.citations
            })
        });

        const data = await response.json();

        if (response.ok) {
            alert(`Draft Submitted to Legal Queue!\nTicket ID: ${data.ticket.id}`);
            onViewChange(View.LEGAL_QUEUE);
        } else {
            alert('Error submitting draft: ' + data.error);
        }
    } catch (e) {
        alert('Network error connecting to Sentinel Core.');
        console.error(e);
    } finally {
        setIsSubmitting(false);
    }
  };

