import React, { useState, useEffect } from 'react';
import LegalGateModal from './LegalGateModal';

const LegalQueue: React.FC = () => {
  const [selectedTicket, setSelectedTicket] = useState<any>(null);
  const [tickets, setTickets] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchQueue = async () => {
    setLoading(true);
    try {
        const token = localStorage.getItem('token') || 'mock-token'; 
        // Note: For demo login logic, ensure user role is 'Legal-Auditor' to access this endpoint
        const res = await fetch('http://localhost:8080/api/v1/legal/queue', {
            headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.queue) {
            setTickets(data.queue);
        }
    } catch (e) {
        console.error("Failed to fetch legal queue", e);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    fetchQueue();
  }, []);

  const handleApprove = async (signature: string) => {
    if (!selectedTicket) return;

    try {
