                'X-Sentinel-2FA': 'true' // Simulating 2FA flag requirement if needed by middleware
            },
            body: JSON.stringify({
                ticket_id: selectedTicket.id,
                decision: 'APPROVED',
                signature: signature,
                totp_code: '123456' // In a real flow, this comes from the modal input
            })
        });

        const data = await res.json();
        if (res.ok) {
             alert(`Ticket Approved Successfully.\nApproval Hash: ${data.approval_hash}`);
             setTickets(prev => prev.filter(t => t.id !== selectedTicket.id));
             setSelectedTicket(null);
        } else {
            alert(`Approval Failed: ${data.error}`);
        }
    } catch (e) {
        alert("Network error during approval.");
