                                {t.risk || 'MEDIUM'}
                            </span>
                        </td>
                        <td className="p-4">
                            <div className="flex gap-1 flex-wrap max-w-[150px]">
                                {t.citations && t.citations.length > 0 ? t.citations.map((c: string, i: number) => (
