package api

import (
	"crypto/sha256"
	"encoding/csv"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"math"
	"strconv"
	"time"

	"github.com/gofiber/fiber/v2"
	"github.com/google/uuid"
)

// Data Structures
type BOMItem struct {
	Name            string  `json:"name"`
	HSCode          string  `json:"hs_code"`
	Quantity        float64 `json:"quantity"`
	UnitPriceLocal  float64 `json:"unit_price_local"`
	UnitPriceImport float64 `json:"unit_price_import"`
}

type CalculationResult struct {
	ID                  string    `json:"id"`
	FileSHA256          string    `json:"file_sha256"`
	UploaderID          string    `json:"uploader_id"`
	TotalCost           float64   `json:"total_cost"`
	LocalContentValue   float64   `json:"local_content_value"`
	LocalContentPercent float64   `json:"local_content_percent"`
	Status              string    `json:"status"` // CLASS_I, CLASS_II, NON_LOCAL
	Items               []BOMItem `json:"items"`
	Timestamp           time.Time `json:"timestamp"`
	IsOverridden        bool      `json:"is_overridden"`
	OverrideReason      string    `json:"override_reason,omitempty"`
}

type OverrideRequest struct {
	CalculationID string `json:"calculation_id"`
	NewStatus     string `json:"new_status"`
	Reason        string `json:"reason"`
	AuditorID     string `json:"auditor_id"`
}

// In-memory store
var Calculations = make(map[string]CalculationResult)
var AuditOverrides = []map[string]interface{}{}

// CalculateL1Handler parses CSV and calculates LC%
func CalculateL1Handler(c *fiber.Ctx) error {
	file, err := c.FormFile("bom_csv")
	if err != nil {
		return c.Status(400).JSON(fiber.Map{"error": "CSV file required"})
	}

	src, err := file.Open()
	if err != nil {
		return c.Status(500).JSON(fiber.Map{"error": "Failed to open file"})
	}
	defer src.Close()

	// Compute SHA256
	hash := sha256.New()
	if _, err := io.Copy(hash, src); err != nil {
		return c.Status(500).JSON(fiber.Map{"error": "Hashing failed"})
	}
	fileHash := hex.EncodeToString(hash.Sum(nil))

	// Reset file pointer for CSV reading
	src.Seek(0, 0)
	reader := csv.NewReader(src)
	records, err := reader.ReadAll()
	if err != nil {
		return c.Status(400).JSON(fiber.Map{"error": "Invalid CSV format"})
	}

	var items []BOMItem
	var totalCost, totalLocal float64

	// Skip header (Row 0)
	for i, record := range records {
		if i == 0 {
			continue
		}
		if len(record) < 5 {
			continue
		}

		qty, _ := strconv.ParseFloat(record[2], 64)
		priceLocal, _ := strconv.ParseFloat(record[3], 64)
		priceImport, _ := strconv.ParseFloat(record[4], 64)

		if qty < 0 || priceLocal < 0 || priceImport < 0 {
			return c.Status(400).JSON(fiber.Map{"error": fmt.Sprintf("Negative values found at row %d", i+1)})
		}

		itemCost := qty * (priceLocal + priceImport)
		itemLocal := qty * priceLocal

		totalCost += itemCost
		totalLocal += itemLocal

		items = append(items, BOMItem{
			Name:            record[0],
			HSCode:          record[1],
			Quantity:        qty,
			UnitPriceLocal:  priceLocal,
			UnitPriceImport: priceImport,
		})
	}

	lcPercent := 0.0
	if totalCost > 0 {
		lcPercent = (totalLocal / totalCost) * 100
	}

	status := "NON_LOCAL"
	if lcPercent >= 50.0 {
		status = "CLASS_I"
	} else if lcPercent >= 20.0 {
		status = "CLASS_II"
	}

	calcID := uuid.New().String()
	result := CalculationResult{
		ID:                  calcID,
		FileSHA256:          fileHash,
		UploaderID:          "Vendor-User-001", // Mock Context
		TotalCost:           math.Round(totalCost*100) / 100,
		LocalContentValue:   math.Round(totalLocal*100) / 100,
		LocalContentPercent: math.Round(lcPercent*100) / 100,
		Status:              status,
		Items:               items,
		Timestamp:           time.Now(),
	}

	Calculations[calcID] = result

	return c.JSON(result)
}

// OverrideL1Handler allows legal auditor to force a classification
func OverrideL1Handler(c *fiber.Ctx) error {
	var req OverrideRequest
	if err := c.BodyParser(&req); err != nil {
		return c.Status(400).JSON(fiber.Map{"error": "Invalid payload"})
	}

	calc, exists := Calculations[req.CalculationID]
	if !exists {
		return c.Status(404).JSON(fiber.Map{"error": "Calculation ID not found"})
	}

	// Immutable Log
	auditEntry := map[string]interface{}{
		"event":         "L1_OVERRIDE",
		"calculation_id": req.CalculationID,
		"old_status":    calc.Status,
		"new_status":    req.NewStatus,
		"reason":        req.Reason,
		"auditor_id":    req.AuditorID,
		"timestamp":     time.Now(),
	}
	AuditOverrides = append(AuditOverrides, auditEntry)

	// Apply Override
	calc.Status = req.NewStatus
	calc.IsOverridden = true
	calc.OverrideReason = req.Reason
	Calculations[req.CalculationID] = calc

	log.Printf("[AUDIT] L1 OVERRIDE: ID=%s Auditor=%s Reason=%s", req.CalculationID, req.AuditorID, req.Reason)

	return c.JSON(calc)
}

// SimulateSensitivityHandler calculates impact of changes
func SimulateSensitivityHandler(c *fiber.Ctx) error {
	type SimulationRequest struct {
		Items []BOMItem `json:"items"`
	}
	var req SimulationRequest
	if err := c.BodyParser(&req); err != nil {
		return c.Status(400).JSON(fiber.Map{"error": "Invalid items"})
	}

	var totalCost, totalLocal float64
	for _, item := range req.Items {
		totalCost += item.Quantity * (item.UnitPriceLocal + item.UnitPriceImport)
		totalLocal += item.Quantity * item.UnitPriceLocal
	}

	lcPercent := 0.0
	if totalCost > 0 {
		lcPercent = (totalLocal / totalCost) * 100
	}

	// Simple heuristic for PWin (Probability of Win) delta
	// Assuming Class-I (50%+) gives 20% margin preference
	pWinBase := 50.0 // Base probability
	if lcPercent >= 50.0 {
		pWinBase += 25.0 // High pref
	} else if lcPercent >= 20.0 {
		pWinBase += 10.0 // Entry level
	}

	return c.JSON(fiber.Map{
		"projected_lc_percent": math.Round(lcPercent*100) / 100,
		"projected_pwin":       pWinBase,
		"total_cost":           totalCost,
	})
}

package api

import (
	"bytes"
	"mime/multipart"
	"net/http/httptest"
	"testing"

	"github.com/gofiber/fiber/v2"
)

func TestCalculateL1_EdgeCases(t *testing.T) {
	app := fiber.New()
	app.Post("/calc", CalculateL1Handler)

	tests := []struct {
		name       string
		csvContent string
		wantStatus int
		wantLC     float64 // Check output JSON manually if needed, or status code for errors
	}{
		{
			name: "Valid Class-I",
			csvContent: "Item,HS,Qty,Local,Import\nA,123,10,100,0\nB,456,5,0,20", // Total: 1000 Local + 100 Import = 1100. LC: 1000/1100 = 90.9%
			wantStatus: 200,
		},
		{
			name: "Zero Total Cost",
			csvContent: "Item,HS,Qty,Local,Import\nA,123,10,0,0",
			wantStatus: 200, // Should return 0% LC, not crash
		},
		{
			name: "Negative Value",
			csvContent: "Item,HS,Qty,Local,Import\nA,123,-5,100,0",
			wantStatus: 400,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			body := new(bytes.Buffer)
			writer := multipart.NewWriter(body)
			part, _ := writer.CreateFormFile("bom_csv", "test.csv")
			part.Write([]byte(tt.csvContent))
			writer.Close()

			req := httptest.NewRequest("POST", "/calc", body)
			req.Header.Set("Content-Type", writer.FormDataContentType())

			resp, _ := app.Test(req)

			if resp.StatusCode != tt.wantStatus {
				t.Errorf("Expected status %d, got %d", tt.wantStatus, resp.StatusCode)
			}
		})
	}
}

import React, { useState, useEffect } from 'react';
import { CalculatorItem } from '../types';

interface BOMItemData {
  name: string;
  hs_code: string;
  quantity: number;
  unit_price_local: number;
  unit_price_import: number;
}

const Calculator: React.FC = () => {
  // Mode: Manual or File
  const [isSimulating, setIsSimulating] = useState(false);
  const [items, setItems] = useState<BOMItemData[]>([]);
  const [uploadData, setUploadData] = useState<any>(null); // To store backend calculation result
  const [projectedLC, setProjectedLC] = useState<number>(0);
  const [projectedPWin, setProjectedPWin] = useState<number>(0);

  // Manual fallback state if not using file
  const [localContentPercent, setLocalContentPercent] = useState(0);
  const [totalCost, setTotalCost] = useState(0);
  const [totalLocal, setTotalLocal] = useState(0);
  const [totalImport, setTotalImport] = useState(0);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;

    const file = e.target.files[0];
    const formData = new FormData();
    formData.append("bom_csv", file);

    try {
        const token = localStorage.getItem('token') || 'mock-token';
        const res = await fetch('http://localhost:8080/api/v1/calculator/calculate', {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${token}` },
            body: formData
        });

        const data = await res.json();
        if (res.ok) {
            setItems(data.items);
            setUploadData(data);
            setLocalContentPercent(data.local_content_percent);
            setTotalCost(data.total_cost);
            setTotalLocal(data.local_content_value);
            setTotalImport(data.total_cost - data.local_content_value);
        } else {
            alert("Error parsing CSV: " + data.error);
        }
    } catch (e) {
        alert("Network error.");
    }
  };

  const runSimulation = async (updatedItems: BOMItemData[]) => {
      try {
        const token = localStorage.getItem('token') || 'mock-token';
        const res = await fetch('http://localhost:8080/api/v1/calculator/simulate', {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}` 
            },
            body: JSON.stringify({ items: updatedItems })
        });
        const data = await res.json();
        if (res.ok) {
            setProjectedLC(data.projected_lc_percent);
            setProjectedPWin(data.projected_pwin);
        }
      } catch (e) {
          console.error(e);
      }
  };

