package middleware

import (
	"github.com/gofiber/fiber/v2"
	"strings"
)

// LegalExportGate ensures that any resource being exported or finalized 
// has a valid legal approval signature in its context or query params.
// In a real DB-backed app, this would check the 'status' column of the resource.
// For the pilot, we check for a 'legal_approved=true' flag or signature presence in request.
func LegalExportGate(c *fiber.Ctx) error {
	// 1. Skip check for non-export routes (safeguard)
	if !strings.Contains(c.Path(), "/export") && !strings.Contains(c.Path(), "/manifest/generate") {
		return c.Next()
	}

	// 2. Check for Approval Evidence
	// In the pilot integration, the frontend sends the approval hash if it exists.
	// Or we check the in-memory store status (if ID is provided).

	// Option A: Check Query Param (Simulated for stateless calls)
	approvalSignature := c.Query("approval_signature")

	// Option B: Check Body (if JSON)
	if approvalSignature == "" {
		var body map[string]interface{}
		// We try to parse body without consuming it permanently if possible, 
		// but Fiber BodyParser consumes the stream. 
		// Ideally, we rely on the upstream handler to verify status, 
		// OR we enforce a specific header "X-Sentinel-Legal-Sig".
		approvalSignature = c.Get("X-Sentinel-Legal-Sig")
	}

	// 3. Enforcement
	if approvalSignature == "" {
		return c.Status(403).JSON(fiber.Map{
			"error": "EXPORT_LOCKED",
			"message": "Legal Gate enforcement active. Resource requires Legal Auditor approval signature (2FA) before export.",
			"required_action": "Request approval via Legal Queue.",
		})
	}

	// In a real system, we would verify the signature hash integrity here.
	// For pilot, presence is sufficient to demonstrate the gate.

	return c.Next()
}

package api

import (
	"log"
	"time"

	"github.com/gofiber/fiber/v2"
	"github.com/google/uuid"
	"github.com/gov-india/sentinel-bharat/backend/services"
)

// Ticket represents a Pre-Bid Draft awaiting Legal Approval
type Ticket struct {
	ID                string               `json:"id"`
	TenderID          string               `json:"tender_id"`
	ClauseID          string               `json:"clause_id"`
	Title             string               `json:"title"`
	QueryText         string               `json:"query_text"`
	Author            string               `json:"author"`
	RiskLevel         string               `json:"risk"`
	Status            string               `json:"status"` // PENDING, APPROVED, REJECTED, BLOCKED
	Citations         []string             `json:"citations"`
	CreatedAt         time.Time            `json:"created_at"`
	ApprovalSignature string               `json:"approval_signature,omitempty"`
	ApproverID        string               `json:"approver_id,omitempty"`
	Violations        []services.Violation `json:"violations,omitempty"`
	BlockedOutput     bool                 `json:"blocked_output"`
}

// In-memory store for pilot
var TicketStore = []Ticket{}

type CreateDraftRequest struct {
	TenderID   string   `json:"tender_id"`
	ClauseID   string   `json:"clause_id"`
	ClauseText string   `json:"clause_text"`
	Category   string   `json:"category"`
	Tone       string   `json:"tone"`
	Risk       string   `json:"risk"`
	Citations  []string `json:"citations"`
}

// CreateDraftHandler generates a query and creates a ticket
func CreateDraftHandler(c *fiber.Ctx) error {
	var req CreateDraftRequest
	if err := c.BodyParser(&req); err != nil {
		return c.Status(400).JSON(fiber.Map{"error": "Invalid payload"})
	}

	// 1. Verification Check (Mock - assume citations passed are verified if they exist)
	// In production, we'd verify them here against the Verifier Engine.
	citationsVerified := true 
	if len(req.Citations) > 0 {
		// Mock logic: fail verification if citation contains "unverified" string
		for _, cit := range req.Citations {
			if cit == "unverified" { 
				citationsVerified = false 
			}
		}
	}

	// 2. Generate Query Text via Service
	generatedText := services.GenerateQuery(
		req.ClauseID, 
		req.ClauseText, 
		req.Category, 
		req.Tone, 
		req.Citations,
	)

	// 3. Run Policy Rules Engine
	complianceReport := services.ValidateContent(generatedText, citationsVerified)

	status := "PENDING"
	blocked := false
	if complianceReport.Blocked {
		status = "BLOCKED"
		blocked = true
	}

	// 4. Create Ticket
	ticket := Ticket{
		ID:            "TKT-" + uuid.New().String()[:8],
		TenderID:      req.TenderID,
		ClauseID:      req.ClauseID,
		Title:         "Query: " + req.Category,
		QueryText:     generatedText,
		Author:        "Vendor User", // In prod, get from JWT
		RiskLevel:     req.Risk,
		Status:        status,
		Citations:     req.Citations,
		CreatedAt:     time.Now(),
		Violations:    complianceReport.Violations,
		BlockedOutput: blocked,
	}

	TicketStore = append(TicketStore, ticket)

	log.Printf("[AUDIT] DRAFT_CREATED: ID=%s Tender=%s Risk=%s Blocked=%v", ticket.ID, ticket.TenderID, ticket.RiskLevel, blocked)

	if blocked {
		return c.Status(422).JSON(fiber.Map{
			"status": "BLOCKED",
			"error": "Content Policy Violation",
			"ticket": ticket,
			"violations": complianceReport.Violations,
			"message": "Draft blocked by Rules Engine. Legal ticket created automatically.",
		})
	}

	return c.JSON(fiber.Map{
		"status": "CREATED",
		"ticket": ticket,
		"message": "Draft generated and submitted to Legal Queue.",
	})
}

package main

import (
	"log"

	"github.com/gofiber/fiber/v2"
	"github.com/gofiber/fiber/v2/middleware/cors"
	"github.com/gofiber/fiber/v2/middleware/helmet"
	"github.com/gofiber/fiber/v2/middleware/logger"

	"github.com/gov-india/sentinel-bharat/backend/api"
	"github.com/gov-india/sentinel-bharat/backend/auth"
	"github.com/gov-india/sentinel-bharat/backend/config"
	"github.com/gov-india/sentinel-bharat/backend/middleware"
)

func main() {
	// 1. Config & Safety Checks
	cfg := config.Load()
	if cfg.Region != "ap-south-1" {
		log.Printf("WARNING: Data Residency Check Failed. Expected ap-south-1, got %s", cfg.Region)
	}

	// 2. Fiber App
	app := fiber.New(fiber.Config{
		AppName:       "Sentinel Prime Core v1.2",
		ServerHeader:  "Sentinel-Secure",
		CaseSensitive: true,
		StrictRouting: true,
		BodyLimit:     100 * 1024 * 1024,
	})

	// 3. Middleware
	app.Use(logger.New())
	app.Use(helmet.New())
	app.Use(cors.New(cors.Config{
		AllowOrigins: "https://sentinel.gov.in, http://localhost:3000",
		AllowHeaders: "Origin, Content-Type, Accept, Authorization, X-Sentinel-2FA, X-Sentinel-Legal-Sig",
		AllowMethods: "GET, POST, PUT, DELETE, OPTIONS",
	}))

	// 4. Routes
	apiGroup := app.Group("/api/v1")
	authHandler := auth.NewHandler()

	// Auth Routes
	authGroup := apiGroup.Group("/auth")
	authGroup.Post("/login", authHandler.Login)
	authGroup.Post("/refresh", authHandler.Refresh)
	authGroup.Post("/forgot-password", authHandler.RequestPasswordReset)
	authGroup.Post("/admin/approve-reset", auth.RequireRole("Admin"), authHandler.AdminApproveReset)

	// Onboarding Routes
	onboarding := apiGroup.Group("/onboarding")
	onboarding.Post("/register", api.RegisterVendorHandler)

	// Protected Routes (JWT Required)
	protected := apiGroup.Use(auth.JwtMiddleware)

	// Ingestion Routes
	protected.Post("/tenders/ingest", api.IngestTenderHandler)
	protected.Post("/tenders/sync", api.SyncTendersHandler)
	protected.Post("/webhooks/feed", api.CommercialWebhookHandler)

	protected.Get("/analysis/clauses/:id", api.GetClausesHandler)
	protected.Post("/verify/citation", api.VerifyCitationHandler)

	// Pre-Bid Routes
	protected.Post("/prebid/draft", api.CreateDraftHandler)

	// Vault
	vault := protected.Group("/vault")
	vault.Get("/keys", api.GetVaultKeysHandler)
	vault.Post("/wallet/connect", api.ConnectWalletHandler)
	vault.Post("/upload", api.UploadVaultFileHandler)
	vault.Post("/map", api.MapEvidenceHandler)
	vault.Post("/verify", api.VerifyEvidenceHandler)

	// SENSITIVE: Manifest Generation requires Legal Gate
	vault.Post("/manifest/generate", middleware.LegalExportGate, api.GenerateManifestHandler)
	vault.Post("/sign-manifest", middleware.LegalExportGate, api.SignManifestHandler) 

	// Legal Routes (RBAC Enforced)
	legal := protected.Use(auth.RequireRole("Legal-Auditor", "Admin"))
	legal.Get("/legal/queue", api.GetLegalQueueHandler)
	legal.Post("/legal/approve", auth.Require2FA, api.ApproveTicketHandler)
	legal.Post("/calculator/override", auth.Require2FA, api.OverrideL1Handler)

	// Calculator Routes
	calc := protected.Group("/calculator")
	calc.Post("/calculate", api.CalculateL1Handler)
	calc.Post("/simulate", api.SimulateSensitivityHandler)

	// 5. Start
	log.Printf("Sentinel Prime Core active on :%s (Region: %s)", cfg.Port, cfg.Region)
	log.Fatal(app.Listen(":" + cfg.Port))
}

import React from 'react';

interface PWinGaugeProps {
  score: number;       // 0-100
  confidence: number;  // Margin of error (e.g., +/- 5%)
  size?: number;
}

const PWinGauge: React.FC<PWinGaugeProps> = ({ score, confidence, size = 120 }) => {
  const radius = size / 2;
  const strokeWidth = size * 0.1;
  const normalizedRadius = radius - strokeWidth * 2;
  const circumference = normalizedRadius * 2 * Math.PI;

  // Arc logic (semi-circle)
  const offset = circumference - (score / 100) * (circumference / 2);
  const rotation = -180; // Start from left

  // Confidence band calculations
  const lowerBound = Math.max(0, score - confidence);
  const upperBound = Math.min(100, score + confidence);

  const lowerOffset = circumference - (lowerBound / 100) * (circumference / 2);
  const upperOffset = circumference - (upperBound / 100) * (circumference / 2);
  const bandLength = lowerOffset - upperOffset;

  let color = 'text-red-500';
  if (score > 40) color = 'text-yellow-500';
  if (score > 70) color = 'text-green-500';

  return (
    <div className="relative flex flex-col items-center justify-center" style={{ width: size, height: size / 1.5 }}>
      <svg
        height={size}
        width={size}
        className="transform -rotate-90 overflow-visible"
      >
        {/* Background Track */}
        <circle
          stroke="rgba(51, 65, 85, 0.5)"
          strokeWidth={strokeWidth}
          strokeDasharray={`${circumference / 2} ${circumference}`}
          fill="transparent"
          r={normalizedRadius}
          cx={radius}
          cy={radius}
        />

        {/* Confidence Band (Subtle) */}
        <circle
          stroke="currentColor"
          className="text-slate-700 opacity-30"
          strokeWidth={strokeWidth * 1.5}
          strokeDasharray={`${(upperBound - lowerBound) / 100 * (circumference / 2)} ${circumference}`}
          strokeDashoffset={-1 * (lowerBound / 100) * (circumference / 2)}
          fill="transparent"
          r={normalizedRadius}
          cx={radius}
          cy={radius}
        />

        {/* Score Arc */}
        <circle
          stroke="currentColor"
          className={`${color} transition-all duration-1000 ease-out`}
          strokeWidth={strokeWidth}
          strokeDasharray={`${circumference / 2} ${circumference}`}
          strokeDashoffset={offset}
          fill="transparent"
          r={normalizedRadius}
          cx={radius}
          cy={radius}
        />
      </svg>

      {/* Value Text */}
      <div className="absolute top-[60%] flex flex-col items-center">
        <span className={`text-2xl font-bold font-mono ${color}`}>
          {score}%
        </span>
        <span className="text-[10px] text-slate-500 font-medium">
          ±{confidence}% Conf.
        </span>
      </div>
    </div>
  );
};

export default PWinGauge;

