    statusBorder = 'border-teal-500';
    progressColor = 'bg-teal-500';
    statusTitle = 'Class-I Local Supplier';
    statusDesc = 'Eligible for Purchase Preference (Top Priority). Content > 50%.';
  } else if (currentPercent >= 20.0) {
