  const [selectedClause, setSelectedClause] = useState<string | null>(null);
  const [mappings, setMappings] = useState<Record<string, string>>({}); // ClauseID -> FileID
  const [verifying, setVerifying] = useState<Record<string, boolean>>({}); // ClauseID -> boolean
  const [manifestData, setManifestData] = useState<any>(null);

  // Fetch Keys on Load
  useEffect(() => {
    // Mock Fetch
    setPublicKeys([
      { id: 'key-ap-south-1-001', algo: 'RSA-2048', thumb: 'a1b2c3...', created: '2023-10-01' }
    ]);
  }, []);

  const handleConnectWallet = () => {
    // Simulate Connect
    setTimeout(() => {
      setWalletConnected(true);
    }, 800);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setIsUploading(true);
      const file = e.target.files[0];
      const formData = new FormData();
      formData.append('file', file);

      try {
          const token = localStorage.getItem('token') || 'mock-token';
          // Try fetching from real backend first
          const res = await fetch('http://localhost:8080/api/v1/vault/upload', {
              method: 'POST',
              headers: { 'Authorization': `Bearer ${token}` },
              body: formData
          });

          if (!res.ok) throw new Error("Upload failed or backend unavailable");

          const newFile = await res.json();
          setFiles(prev => [...prev, newFile]);
      } catch (err) {
          console.warn("Backend unavailable, switching to local simulation.", err);
          // FALLBACK SIMULATION for Demo
          setTimeout(() => {
              const mockFile: VaultFile = {
                  id: "v-local-" + Math.floor(Math.random() * 10000),
                  filename: file.name,
                  version: 1,
                  size: file.size,
                  file_sha256: "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
                  upload_time: new Date().toISOString(),
                  verified: false,
                  tags: ["Uploaded", "Simulated"],
                  expiry_date: "2025-12-31"
              };
              setFiles(prev => [...prev, mockFile]);
              setIsUploading(false);
          }, 1500);
          return; // Exit early so finally doesn't run twice or prematurely
      } finally {
          // If successful (not caught), stop loading
          setIsUploading(false);
      }
    }
  };

  const handleMapEvidence = (fileId: string) => {
    if (!selectedClause) return;
    setMappings(prev => ({ ...prev, [selectedClause]: fileId }));

    // Auto-verify simulation
    setVerifying(prev => ({ ...prev, [selectedClause]: true }));
    setTimeout(() => {
      setVerifying(prev => ({ ...prev, [selectedClause]: false }));
      setFiles(prev => prev.map(f => f.id === fileId ? { ...f, verified: true } : f));
    }, 1500);
  };

  const handleGenerateManifest = async () => {
      try {
          const token = localStorage.getItem('token') || 'mock-token';
          const res = await fetch('http://localhost:8080/api/v1/vault/manifest/generate', {
              method: 'POST',
              headers: { 
                  'Authorization': `Bearer ${token}`,
                  'Content-Type': 'application/json'
              },
              body: JSON.stringify({}) // Backend uses existing mappings state for pilot
          });

          const data = await res.json();
          if (res.ok) {
              setManifestData(data);
              setShowManifestModal(true);
          } else {
              // Fallback for demo
              throw new Error("Backend offline");
