                  <div>
                    <h1 className="text-xl font-bold uppercase tracking-wide font-header text-slate-900">Extracted Content</h1>
                    <p className="text-xs text-slate-500 mt-1 font-mono">REF: {file.name.toUpperCase()}</p>
