import React, { useState, useEffect } from 'react';
import { View, User } from '../types';
import Sidebar from './Sidebar';
import Dashboard from './Dashboard';
import Analyzer from './Analyzer';
import PreBidStudio from './PreBidStudio';
import Calculator from './Calculator';
import Vault from './Vault';
import Login from './Login';
import Onboarding from './Onboarding';
import IngestStation from './IngestStation';
import LegalQueue from './LegalQueue';
import VerificationModal from './VerificationModal';

// Extend window interface for map popup navigation
declare global {
  interface Window {
    navigateToView: (viewName: string) => void;
  }
}

export default function App() {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [preBidContext, setPreBidContext] = useState<any>(null);

  // Expose navigation to window for Leaflet popups
  useEffect(() => {
    window.navigateToView = (viewName: string) => {
      if (Object.values(View).includes(viewName as View)) {
        setCurrentView(viewName as View);
      }
    };
  }, []);

  const handleLogin = (user: User) => {
      setCurrentUser(user);
      // Simulate first-time login check
      if (user.name === 'New Vendor') {
          setShowOnboarding(true);
      } else {
          setCurrentView(View.DASHBOARD);
      }
  };

  const handleOnboardingComplete = () => {
      setShowOnboarding(false);
      setCurrentView(View.DASHBOARD);
  };

  // SVG User Profile Base64
  const userProfileSvg = `data:image/svg+xml;base64,`;

  const renderView = () => {
    if (showOnboarding) {
        return <Onboarding onComplete={handleOnboardingComplete} />;
    }
    switch (currentView) {
      case View.DASHBOARD:
        return <Dashboard onViewChange={setCurrentView} />;
      case View.INGEST:
        return <IngestStation />;
      case View.ANALYZER:
        return <Analyzer onViewChange={setCurrentView} onSetContext={setPreBidContext} />;
      case View.PREBID:
        return <PreBidStudio onViewChange={setCurrentView} onOpenModal={() => setIsModalOpen(true)} contextData={preBidContext} />;
      case View.CALCULATOR:
        return <Calculator />;
      case View.VAULT:
        return <Vault />;
      case View.LEGAL_QUEUE:
        return <LegalQueue />;
      case View.ONBOARDING:
        return <Onboarding onComplete={handleOnboardingComplete} />;
      default:
        return <Dashboard onViewChange={setCurrentView} />;
    }
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex h-screen overflow-hidden text-sm bg-slate-950 text-slate-200 font-inter">
      {/* Sidebar */}
      {!showOnboarding && <Sidebar currentView={currentView} onViewChange={setCurrentView} />}

      {/* Main Content */}
      <main className="flex-1 flex flex-col relative bg-slate-950">
        {/* Header */}
        {!showOnboarding && (
            <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-md sticky top-0 z-10 shrink-0">
            <div className="flex items-center gap-4">
                <span className="px-2 py-1 bg-gov-warning/10 text-gov-warning text-xs font-mono rounded border border-gov-warning/20 animate-pulse flex items-center gap-2 font-bold">
                <span className="w-2 h-2 rounded-full bg-gov-warning"></span>
                LIVE FEED ACTIVE
                </span>
                <span className="text-slate-400 text-xs hidden sm:inline">
                Last Sync: <span className="font-mono text-cyan-400">14:02:45 IST</span>
                </span>
                <span className="text-[10px] text-slate-600 font-mono hidden lg:block border border-slate-800 px-2 py-0.5 rounded">
                AI MODEL: SENTINEL-CORE-V2
                </span>
            </div>
            <div className="flex items-center gap-4">
                <button className="p-2 text-slate-400 hover:text-white relative transition-colors">
                <span className="material-symbols-outlined">notifications</span>
                <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full animate-ping"></span>
                <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full"></span>
                </button>
                <div className="flex items-center gap-3 pl-4 border-l border-slate-800">
                <div className="text-right hidden sm:block">
                    <p className="text-white font-medium text-xs">{currentUser.name}</p>
                    <p className="text-[10px] text-cyan-500 font-mono">{currentUser.designation}</p>
                </div>
                <div className="w-9 h-9 rounded-full bg-slate-800 p-0.5 border border-slate-700 overflow-hidden">
                    <img alt="User" className="w-full h-full object-cover rounded-full" src={userProfileSvg} />
                </div>
                </div>
            </div>
            </header>
        )}

        {/* View Container */}
        <div className="flex-1 overflow-y-auto overflow-x-hidden p-6 relative">
          {renderView()}
        </div>
      </main>

      {/* Modal */}
      <VerificationModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { View } from '../types';

declare global {
  interface Window {
    pdfjsLib: any;
  }
}

interface AnalyzerProps {
  onViewChange: (view: View) => void;
  onSetContext?: (context: any) => void;
}

// Definition for extracted section
interface PdfSection {
  id: string;
  title: string;
  text: string;
  page: number;
  risky?: boolean;
  riskLevel?: 'CRITICAL' | 'HIGH' | 'LOW';
  citations?: string[];
}

const Analyzer: React.FC<AnalyzerProps> = ({ onViewChange, onSetContext }) => {
  const [file, setFile] = useState<File | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [scanProgress, setScanProgress] = useState(0);
  const [scanComplete, setScanComplete] = useState(false);
  const [selectedClauseId, setSelectedClauseId] = useState<string | null>(null);
  const [logs, setLogs] = useState<string[]>([]);
  const [riskScore, setRiskScore] = useState(0);
  const [extractedSections, setExtractedSections] = useState<PdfSection[]>([]);

  const logsEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Auto-scroll logs
  useEffect(() => {
    if (logsEndRef.current) {
      logsEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [logs]);

  const addLog = (message: string) => {
    const timestamp = new Date().toISOString().split('T')[1].slice(0, 8);
    setLogs(prev => [...prev, `[${timestamp}] ${message}`]);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const selectedFile = e.target.files[0];
      setFile(selectedFile);
      setScanComplete(false);
      setRiskScore(0);
      setLogs([]);
      setExtractedSections([]);
      addLog(`Secure File Mount: ${selectedFile.name}`);
      addLog(`Size: ${(selectedFile.size / 1024).toFixed(2)} KB | Type: ${selectedFile.type || 'application/pdf'}`);
      addLog("Ready for deep inspection.");
    }
  };

  // Real Risk Keyword Dictionary
  const riskRules = [
    {
      keywords: [/foreign/i, /outside india/i, /united states/i, /europe/i, /singapore/i],
      context: [/hosting/i, /data center/i, /cloud/i, /storage/i],
      level: 'CRITICAL',
      label: 'Data Residency Violation',
      citations: ['MeitY Cloud Guidelines', 'DPDP Act 2023 Sec 17']
    },
    {
      keywords: [/turnover/i, /revenue/i],
      context: [/500/i, /billion/i, /million dollar/i, /5000/i], // detecting unreasonably high numbers
      level: 'HIGH',
      label: 'Restrictive Turnover Criteria',
      citations: ['GFR 2017 Rule 172', 'MSME Policy 2012']
    },
    {
      keywords: [/specific brand/i, /cisco/i, /hp/i, /dell/i, /oracle/i, /proprietary/i],
      context: [/must/i, /shall/i, /only/i, /mandatory/i],
      level: 'HIGH',
      label: 'Brand Favoritism (Restrictive)',
      citations: ['CVC Circular 03/01/18', 'GFR 2017 Rule 144(i)']
    },
    {
        keywords: [/payment/i, /advance/i],
        context: [/100%/i, /full/i, /prior/i],
        level: 'CRITICAL',
        label: 'Unsecured Advance Payment',
        citations: ['GFR 2017 Rule 172(1)']
    },
    {
        keywords: [/experience/i, /years/i],
        context: [/15 years/i, /20 years/i, /global/i],
        level: 'HIGH',
        label: 'Excessive Experience Req',
        citations: ['CVC Guidelines on Pre-Qualification']
    }
  ];

  // Real Analysis Engine
  const performAnalysis = async (file: File) => {
    if (!window.pdfjsLib) {
        addLog("ERROR: PDF Engine not loaded. Check internet connection.");
        setIsScanning(false);
        return;
    }

    try {
        const arrayBuffer = await file.arrayBuffer();
        const pdf = await window.pdfjsLib.getDocument({ data: arrayBuffer }).promise;

        addLog(`PDF Loaded. Page Count: ${pdf.numPages}`);
        addLog("Initializing Optical Character Recognition (Text Layer)...");

        let fullClauses: PdfSection[] = [];
        let totalRisks = 0;

        for (let i = 1; i <= pdf.numPages; i++) {
            const page = await pdf.getPage(i);
            const textContent = await page.getTextContent();

            // Extract and clean text
            const pageText = textContent.items.map((item: any) => item.str).join(" ");

            // Simple chunking for demo robustness on real files
            const chunks = pageText.match(/[^.!?]+[.!?]+/g) || [pageText];

            chunks.forEach((chunk, idx) => {
                if (chunk.length < 50) return; // Skip noise

                let riskLevel: 'CRITICAL' | 'HIGH' | 'LOW' | undefined;
                let isRisky = false;
                let activeCitations: string[] = [];
                let riskTitle = "";

                // Run Rules Engine
                for (const rule of riskRules) {
                    const hasKeyword = rule.keywords.some(rx => rx.test(chunk));
                    const hasContext = rule.context.some(rx => rx.test(chunk));

                    if (hasKeyword && hasContext) {
                        isRisky = true;
                        riskLevel = rule.level as any;
                        activeCitations = rule.citations;
                        riskTitle = rule.label;
                        totalRisks++;
                        break; // Stop at first major risk per clause
                    }
                }

                fullClauses.push({
                    id: `cl-${i}-${idx}`,
                    title: isRisky ? `Page ${i}: ${riskTitle}` : `Page ${i} - Clause ${idx + 1}`,
                    text: chunk.trim(),
                    page: i,
                    risky: isRisky,
                    riskLevel: riskLevel,
                    citations: activeCitations
                });
            });

            setScanProgress(Math.round((i / pdf.numPages) * 100));
            if (i % 2 === 0) addLog(`Processed Page ${i}...`);
        }

        if (fullClauses.length === 0) {
            addLog("Warning: No readable text found. Document might be scanned image.");
            fullClauses.push({
                id: 'err-1',
                title: 'Parsing Error',
                text: 'Could not extract text layer. Please use OCR-enabled PDF.',
                page: 1,
                risky: false
            });
        } else {
            addLog(`Analysis Complete. ${fullClauses.length} segments analyzed.`);
            addLog(`Found ${totalRisks} potential compliance risks.`);
        }

        setExtractedSections(fullClauses);

        // Calculate score based on findings
        const score = Math.min(100, totalRisks * 20); 
        setRiskScore(score);

        setScanComplete(true);
        // Select first risky clause if any
        const firstRisky = fullClauses.find(c => c.risky);
        if (firstRisky) setSelectedClauseId(firstRisky.id);

    } catch (e: any) {
        console.error(e);
        addLog(`CRITICAL ERROR: ${e.message}`);
    } finally {
        setIsScanning(false);
    }
  };

  const triggerScan = () => {
    if (!file) return;
    setIsScanning(true);
    setScanProgress(0);
    setLogs([]);
    setRiskScore(0);

    addLog("Initiating Sentinel Core...");
    // Small delay to allow UI to update
    setTimeout(() => {
        performAnalysis(file);
    }, 500);
  };

  const handleClauseClick = (id: string) => {
    setSelectedClauseId(id);
  };

  const handleGenerateDefense = (activeClause: PdfSection) => {
      if (onSetContext) {
          onSetContext({
              tenderId: file?.name || "Unknown Tender",
              clauseId: activeClause.id,
              clauseText: activeClause.text,
              category: activeClause.title,
              risk: activeClause.riskLevel,
              citations: activeClause.citations
          });
      }
      onViewChange(View.PREBID);
  };

  const getRiskLevel = (score: number) => {
      if (score >= 60) return { label: 'CRITICAL', color: 'text-red-500', bg: 'bg-red-500' };
      if (score >= 30) return { label: 'HIGH', color: 'text-gov-warning', bg: 'bg-yellow-500' };
      if (score > 0) return { label: 'MODERATE', color: 'text-orange-400', bg: 'bg-orange-500' };
      return { label: 'LOW', color: 'text-teal-400', bg: 'bg-teal-500' };
  };

  const currentRisk = getRiskLevel(riskScore);

  return (
    <div className="space-y-6 h-full flex flex-col fade-in text-slate-200">
      {/* Top Header */}
      <div className="flex justify-between items-center bg-navy-900/50 border-b border-slate-700 pb-4">
        <div>
            <h2 className="text-2xl font-bold text-white font-header tracking-wide flex items-center gap-2">
              <span className="material-symbols-outlined text-teal-400">analytics</span>
              RFP ANALYZER (Live Engine)
            </h2>
            <p className="text-xs text-slate-500 font-mono mt-1">SENTINEL INTELLIGENCE CORE // V2.4</p>
        </div>
        <div className="flex items-center gap-6">
             {riskScore > 0 && (
                 <div className="flex items-center gap-3 px-4 py-2 rounded border border-red-500/30 bg-red-500/10 animate-pulse">
                    <span className="material-symbols-outlined text-red-500">warning</span>
                    <div className="text-right">
                      <p className="text-[10px] text-red-400 font-bold uppercase tracking-wider">Aggregate Risk</p>
                      <div className="flex items-baseline gap-2">
                          <p className="text-xl font-bold text-white leading-none font-header">{riskScore}/100</p>
                          <span className={`text-[10px] font-bold ${currentRisk.color}`}>{currentRisk.label}</span>
                      </div>
                    </div>
                 </div>
             )}
        </div>
      </div>

      {/* Main Workspace */}
      <div className="grid grid-cols-12 gap-6 flex-1 min-h-0">

        {/* Left: PDF Content Viewer */}
        <div className={`col-span-12 lg:col-span-7 glass-panel rounded-lg overflow-hidden flex flex-col relative scanner-container ${isScanning ? 'scanning' : ''}`}>

          {/* File Upload / Status Header */}
          <div className="bg-slate-900 p-4 border-b border-slate-700 flex justify-between items-center">
            {file ? (
              <div className="flex items-center gap-3 bg-slate-800 px-3 py-1.5 rounded border border-slate-700">
                <span className="material-symbols-outlined text-red-400">picture_as_pdf</span>
                <div>
                   <p className="text-sm font-medium text-slate-200 max-w-[200px] truncate">{file.name}</p>
                   <p className="text-[10px] text-slate-500 uppercase tracking-wide">
                       {(file.size / 1024 / 1024).toFixed(2)} MB • {extractedSections.length > 0 ? 'INDEXED' : 'PENDING'}
                   </p>
                </div>
                <button onClick={() => { setFile(null); setExtractedSections([]); }} className="ml-2 text-slate-500 hover:text-red-400">
                    <span className="material-symbols-outlined text-sm">close</span>
                </button>
              </div>
            ) : (
               <div className="flex items-center gap-2 text-slate-500 text-sm">
                   <span className="material-symbols-outlined">folder_off</span>
                   <span>No active document context</span>
               </div>
            )}

            <div className="flex gap-3">
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                accept="application/pdf" 
                className="hidden" 
              />
              {!file && (
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="bg-slate-800 hover:bg-slate-700 text-slate-300 px-4 py-2 rounded-sm text-xs font-medium border border-slate-600 transition-colors flex items-center gap-2 shadow-sm"
                >
                  <span className="material-symbols-outlined text-sm">upload_file</span>
                  UPLOAD RFP
                </button>
              )}

              <button 
                className={`px-5 py-2 rounded-sm text-xs font-bold uppercase tracking-wider transition-all flex items-center gap-2 ${
                  !file || isScanning 
                    ? 'bg-slate-800 text-slate-600 cursor-not-allowed border border-slate-700' 
                    : 'bg-teal-600 hover:bg-teal-500 text-white shadow-md shadow-teal-900/20 border border-teal-500'
                }`}
                onClick={triggerScan}
                disabled={!file || isScanning}
              >
                {isScanning ? (
                  <>SCANNING {(scanProgress).toFixed(0)}%</>
                ) : (
                  <>INITIATE SCAN</>
                )}
              </button>
            </div>
          </div>

          <div className="scanner-line"></div>

          {/* Document Viewer Area */}
          <div className="flex-1 bg-slate-100 text-slate-900 font-serif text-sm overflow-y-auto relative selection:bg-teal-200 p-8 shadow-inner">
            {!file ? (
              <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-70">
                 <div className="w-20 h-20 border-2 border-dashed border-slate-300 rounded-lg flex items-center justify-center mb-4">
                    <span className="material-symbols-outlined text-4xl">cloud_upload</span>
                 </div>
                 <p className="text-lg font-sans font-semibold text-slate-500">Upload Tender Document</p>
                 <p className="text-xs mt-1 font-mono">SECURE UPLOAD // PDF FORMAT ONLY</p>
              </div>
            ) : !scanComplete && !isScanning ? (
               <div className="h-full flex flex-col items-center justify-center fade-in">
                  <div className="w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mb-4 border border-blue-100">
                    <span className="material-symbols-outlined text-3xl text-blue-500">visibility</span>
                  </div>
                  <p className="text-slate-700 font-sans font-bold text-lg">Document Preview Locked</p>
                  <p className="text-xs text-slate-500 mt-2 font-mono bg-white px-2 py-1 rounded border border-slate-200">
