package api

import (
	"log"
	"time"
	"strconv"

	"github.com/gofiber/fiber/v2"
	"github.com/google/uuid"
	"github.com/gov-india/sentinel-bharat/backend/adapters"
)

// In-Memory Storage for Pilot
var TenderStore = []adapters.TenderMetadata{}

// IngestTenderHandler handles Manual Uploads (Multipart Form)
func IngestTenderHandler(c *fiber.Ctx) error {
	// 1. Parse Metadata
	title := c.FormValue("title")
	refID := c.FormValue("ref_id")
	category := c.FormValue("category")
	valueStr := c.FormValue("value")

	value, _ := strconv.ParseFloat(valueStr, 64)

	// 2. Handle File
	file, err := c.FormFile("pdf_file")
	if err != nil {
		return c.Status(400).JSON(fiber.Map{"error": "PDF File is mandatory"})
	}

	// 3. Mock Save to Storage (S3)
	// In production: s3.Upload(file.Open(), "bucket", "key")
	s3Key := "tenders/manual/" + file.Filename

	// 4. Create Record
	metadata := adapters.TenderMetadata{
		SourceRefID:  refID,
		Title:        title,
		Category:     category,
		ValueINR:     value,
		PublishDate:  time.Now(),
		ClosingDate:  time.Now().AddDate(0, 0, 30), // Default
		Location:     "Manual Upload",
		Organization: "Unknown",
		IsVerified:   false, // Manual uploads are unverified by default
		SourceSystem: "MANUAL",
		DownloadURL:  s3Key,
	}

	// Persist to Store
	TenderStore = append(TenderStore, metadata)

	log.Printf("[AUDIT] MANUAL_INGEST: User=%s Ref=%s File=%s", "unknown", refID, file.Filename)

	return c.JSON(fiber.Map{
		"status": "INGESTED",
		"id":     uuid.New().String(),
		"data":   metadata,
		"message": "Tender uploaded successfully. Status: UNVERIFIED (Pending Operator Review).",
	})
}

// SyncTendersHandler triggers the GeM/CPPP adapters
func SyncTendersHandler(c *fiber.Ctx) error {
	source := c.Query("source", "GEM")

	var adapter adapters.TenderSource

	switch source {
	case "GEM":
		adapter = adapters.NewGeMAdapter("mock-key")
	default:
		return c.Status(400).JSON(fiber.Map{"error": "Unsupported source"})
	}

	tenders, err := adapter.FetchTenders()
	if err != nil {
		return c.Status(500).JSON(fiber.Map{"error": "Adapter fetch failed"})
	}

	// Merge into Store (De-duplication mock logic could go here)
	for _, t := range tenders { 
		exists := false
		for _, existing := range TenderStore {
			if existing.SourceRefID == t.SourceRefID {
				exists = true
				break
			}
		}
		if !exists {
			TenderStore = append(TenderStore, t)
		}
	}

	log.Printf("[AUDIT] ADAPTER_SYNC: Source=%s Count=%d", source, len(tenders))

	return c.JSON(fiber.Map{
		"status": "SYNC_COMPLETE",
		"source": source,
		"new_tenders": len(tenders),
		"data": tenders,
	})
}

// CommercialWebhookHandler receives feed updates (Stub)
func CommercialWebhookHandler(c *fiber.Ctx) error {
	var payload map[string]interface{}
	if err := c.BodyParser(&payload); err != nil {
		return c.Status(400).JSON(fiber.Map{"error": "Invalid Payload"})
	}

	log.Printf("[AUDIT] WEBHOOK_RECEIVED: %v", payload)

	return c.JSON(fiber.Map{"status": "RECEIVED"})
}

import React, { useState, useEffect } from 'react';
import { View, User, AnalyzerState } from '../types';
import Sidebar from './Sidebar';
import Dashboard from './Dashboard';
import Analyzer from './Analyzer';
import PreBidStudio from './PreBidStudio';
import Calculator from './Calculator';
import Vault from './Vault';
import Login from './Login';
import Onboarding from './Onboarding';
import IngestStation from './IngestStation';
import LegalQueue from './LegalQueue';
import VerificationModal from './VerificationModal';

// Extend window interface for map popup navigation
declare global {
  interface Window {
    navigateToView: (viewName: string) => void;
  }
}

export default function App() {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [preBidContext, setPreBidContext] = useState<any>(null);

  // Persist Analyzer Data here so it doesn't vanish on navigation
  const [analyzerState, setAnalyzerState] = useState<AnalyzerState>({
    file: null,
    extractedSections: [],
    riskScore: 0,
    logs: [],
    scanComplete: false
  });

  // Expose navigation to window for Leaflet popups
  useEffect(() => {
    window.navigateToView = (viewName: string) => {
      if (Object.values(View).includes(viewName as View)) {
        setCurrentView(viewName as View);
      }
    };
  }, []);

  const handleLogin = (user: User) => {
      setCurrentUser(user);
      // Simulate first-time login check
      if (user.name === 'New Vendor') {
          setShowOnboarding(true);
      } else {
          setCurrentView(View.DASHBOARD);
      }
  };

  const handleOnboardingComplete = () => {
      setShowOnboarding(false);
      setCurrentView(View.DASHBOARD);
  };

  // SVG User Profile Base64
  const userProfileSvg = `data:image/svg+xml;base64,`;

  const renderView = () => {
    if (showOnboarding) {
        return <Onboarding onComplete={handleOnboardingComplete} />;
    }
    switch (currentView) {
      case View.DASHBOARD:
        return <Dashboard onViewChange={setCurrentView} />;
      case View.INGEST:
        return <IngestStation />;
      case View.ANALYZER:
        return (
          <Analyzer 
            onViewChange={setCurrentView} 
            onSetContext={setPreBidContext} 
            analyzerState={analyzerState}
            setAnalyzerState={setAnalyzerState}
          />
        );
      case View.PREBID:
        return <PreBidStudio onViewChange={setCurrentView} onOpenModal={() => setIsModalOpen(true)} contextData={preBidContext} />;
      case View.CALCULATOR:
        return <Calculator />;
      case View.VAULT:
        return <Vault />;
      case View.LEGAL_QUEUE:
        return <LegalQueue />;
      case View.ONBOARDING:
        return <Onboarding onComplete={handleOnboardingComplete} />;
      default:
        return <Dashboard onViewChange={setCurrentView} />;
    }
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex h-screen overflow-hidden text-sm bg-slate-950 text-slate-200 font-inter">
      {/* Sidebar */}
      {!showOnboarding && <Sidebar currentView={currentView} onViewChange={setCurrentView} />}

      {/* Main Content */}
      <main className="flex-1 flex flex-col relative bg-slate-950">
        {/* Header */}
        {!showOnboarding && (
            <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-md sticky top-0 z-10 shrink-0">
            <div className="flex items-center gap-4">
                <span className="px-2 py-1 bg-gov-warning/10 text-gov-warning text-xs font-mono rounded border border-gov-warning/20 animate-pulse flex items-center gap-2 font-bold">
                <span className="w-2 h-2 rounded-full bg-gov-warning"></span>
                LIVE FEED ACTIVE
                </span>
                <span className="text-slate-400 text-xs hidden sm:inline">
                Last Sync: <span className="font-mono text-cyan-400">14:02:45 IST</span>
                </span>
                <span className="text-[10px] text-slate-600 font-mono hidden lg:block border border-slate-800 px-2 py-0.5 rounded">
                AI MODEL: SENTINEL-CORE-V2
                </span>
            </div>
            <div className="flex items-center gap-4">
                <button className="p-2 text-slate-400 hover:text-white relative transition-colors">
                <span className="material-symbols-outlined">notifications</span>
                <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full animate-ping"></span>
                <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full"></span>
                </button>
                <div className="flex items-center gap-3 pl-4 border-l border-slate-800">
                <div className="text-right hidden sm:block">
                    <p className="text-white font-medium text-xs">{currentUser.name}</p>
                    <p className="text-[10px] text-cyan-500 font-mono">{currentUser.designation}</p>
                </div>
                <div className="w-9 h-9 rounded-full bg-slate-800 p-0.5 border border-slate-700 overflow-hidden">
                    <img alt="User" className="w-full h-full object-cover rounded-full" src={userProfileSvg} />
                </div>
                </div>
            </div>
            </header>
        )}

        {/* View Container */}
        <div className="flex-1 overflow-y-auto overflow-x-hidden p-6 relative">
          {renderView()}
        </div>
      </main>

      {/* Modal */}
      <VerificationModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
    </div>
  );
}

import React, { useState } from 'react';

const IngestStation: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'manual' | 'api'>('manual');
  const [file, setFile] = useState<File | null>(null);
  const [syncStatus, setSyncStatus] = useState<string>('');
  const [syncedItems, setSyncedItems] = useState<any[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [isOfflineMode, setIsOfflineMode] = useState(false);
  const [formData, setFormData] = useState({
    title: '',
    refId: '',
    value: '',
    category: 'Goods'
  });

  const handleManualUpload = async () => {
    if (!file || !formData.refId) return;
    setIsUploading(true);

    const token = localStorage.getItem('token') || 'mock-token';
    const body = new FormData();
    body.append('title', formData.title);
    body.append('ref_id', formData.refId);
    body.append('category', formData.category);
    body.append('value', formData.value);
    body.append('pdf_file', file);

    try {
        const res = await fetch('http://localhost:8080/api/v1/tenders/ingest', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${token}`
            },
            body: body
        });

        if (!res.ok) throw new Error('Backend Unreachable');

        const data = await res.json();
        alert(`Tender Ingested Successfully!\nID: ${data.id}\nStatus: ${data.status}`);
        resetForm();
    } catch (e) {
        console.warn("Backend unavailable, switching to simulation mode.");
        setIsOfflineMode(true);
        // Simulation Fallback
        await new Promise(resolve => setTimeout(resolve, 1500));
        alert(`[OFFLINE MODE] Tender Ingested Locally.\nID: SIM-${Date.now()}\nStatus: UNVERIFIED`);
        resetForm();
    } finally {
        setIsUploading(false);
    }
  };

  const resetForm = () => {
      setFile(null);
      setFormData({ title: '', refId: '', value: '', category: 'Goods' });
  };

  const handleApiSync = async () => {
    setSyncStatus('SYNCING');
    try {
        const token = localStorage.getItem('token') || 'mock-token';
        const res = await fetch('http://localhost:8080/api/v1/tenders/sync?source=GEM', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${token}`
            }
        });

        if (!res.ok) throw new Error('Backend Unreachable');

        const data = await res.json();
        setSyncedItems(data.data || []);
        setSyncStatus('COMPLETE');
    } catch (e) {
        console.warn("Sync failed, using mock data.");
        setIsOfflineMode(true);
        // Fallback Mock Data
        setTimeout(() => {
            setSyncedItems([
                { source_ref_id: "GEM/2024/SIM/001", title: "Simulated: Advanced Drone Defense System", value_inr: 45000000, is_verified: true },
                { source_ref_id: "CPPP/2024/SIM/002", title: "Simulated: Network Infrastructure Upgrade", value_inr: 12000000, is_verified: false },
                { source_ref_id: "GEM/2024/SIM/003", title: "Simulated: Annual Maintenance for HQ", value_inr: 500000, is_verified: true }
            ]);
            setSyncStatus('COMPLETE');
        }, 1500);
    }
  };

  const loadDemoData = () => {
    setFormData({
        title: 'AI-Enabled Perimeter Surveillance System for Eastern Command',
        refId: 'GEM/2025/B/998210',
        value: '25000000',
        category: 'Goods'
    });
    const dummyFile = new File(["dummy content"], "tender_spec_v1.pdf", { type: "application/pdf" });
    setFile(dummyFile);
  };

  return (
    <div className="space-y-6 h-full flex flex-col fade-in text-slate-200">
      <div className="flex justify-between items-center border-b border-slate-700 pb-4">
        <div>
           <h2 className="text-2xl font-bold text-white font-header flex items-center gap-2">
             <span className="material-symbols-outlined text-teal-400">input</span>
             Ingest Station
           </h2>
           <p className="text-xs text-slate-500">Manual Entry & API Sync Gateway</p>
        </div>
        <div className="flex gap-2 items-center">
            {isOfflineMode && (
                <span className="text-[10px] bg-red-500/10 text-red-400 border border-red-500/20 px-2 py-1 rounded font-bold mr-2">
                    OFFLINE MODE
                </span>
            )}
